INSERT INTO door_catalog VALUES('xcs_trip','XCS_TRIP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XCS_TRIP.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,'XCS','//\\//\\  //\\  //  // xCS!STRIPPER V1.1 //   \  \\/  /\\//  //  """"""""""""""""" \\ /\ \ /// / //\  // The best FILE_ID.DIZ',replace('==/\==/\====/\====//  //===========23=02=96=\n //\\//\\  //\\  //  // xCS!STRIPPER V1.1\n//   \  \\/  /\\//  //  """""""""""""""""\n\\ /\ \ /// / //\  // The best FILE_ID.DIZ\n \/ /\/ //\/  //\\// STRIPPER(wildcard!!!)-\n / /\/ /\\/\  \\ \\\    ADDER around !!!!\n// \ \/ \\\ \ \\\\ \\ A /X tool and supports\n\\  \   //\  \///\\// .LHA .LHZ .LZX .DMS\n \\//\\//  \\///  \/ .ZIP .TXT .NFO .DOC ...\n==\/==\/====\//  //=========================\n O yeah ,   //  // it''s with a sexy look ;)\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 02-23-19  TIME: 10:10:33  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',18404,1,0,NULL,NULL,'xcs_trip','scan',1780048843);
INSERT INTO door_catalog VALUES('xmash11','XMASH11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XMASH11.LHA',NULL,'XIM','XMS2File',NULL,'HYDRA',NULL,'/\ / /             -=> LSD Presents <=- / / /\',replace('============================================\n  /\\n / /             -=> LSD Presents <=-\n/ / /\\n\ \/  \   -=> X M A S H  V 1.1 By HYDRA <=-\n \/\ \/\\n  \  /  \ Update to this Disk Masher Program\n   \/ / / that compresses disks with the XPK\n    \  /  Compressor libraries (included!)\n     \/  For MAX Compression and Flexibility\n          Supports File_ID''s,Text,Appending,\n            Virtual Disks (teqdisk), BBS''s\n>>>> Comes with utils and /X Icons too <<<<<\n============================================\n[-]-[ MORE FUN · KEY WEST · OSiRiS EHQ ]-[-]\n[##    <-----> Placebo Effect <----->    ##]\n[-THe ADDiCTiON BBS - 3NDZ V34 aND iSDN !!-]\n','\n',char(10)),'XMASH.guide',replace('@database AutoID.guide\n\n@Node Main "XMASH V1.1 (C) 1994 HYDRA of LSD, Perspex and Radiance!"\n\n\n                           >>> XMASH  V1.1 <<<\n\n                          (C) 1994 Hydra of LSD\n\n  Welcome to XMASH, probably THE best archiver ever designed for your Amiga!\n\n        XMASH is FREE software so copy and spread as much as you like.\n\n                           @{"  What Is XMASH ? " link whatisit}\n\n                           @{"   Installation   " link installation}\n\n                           @{"   Requirements   " link requirements}\n\n                           @{"      Usage       " link usage}\n\n                           @{"  Sysop''s Notes   " link sysop}\n\n                           @{"     History      " link history}\n\n                           @{"     Greetz!      " link greets}\n\n@EndNode\n\n@Node WhatIsIt "What Is XMASH ?"\n\n  What Is XMASH ?\n  ===============\n\n  Right then,  so you''re wondering what the bloody hell Xmash is by now aren''t\n  you ?  Well I supose I better tell you then!\n\n  It''s a small program that lets you read data from a floppy disk and save\n  it in compressed files and then at a later time you can de-compress it back\n  to another disks, simple really!\n\n  Many other program have attempted to do this but there''s always been\n  something wrong with them, DMS for example is alright, but the files it\n  creates are large and sometimes it wont compress disks and doesnt tell\n  you that it hasnt compressed it.\n  Another thing about DMS is it''s error handling!  If you get a CRC or\n  data error it''ll stop dead in it''s tracks, XMASH on the other hand will\n  contine searching the file until it finds more data that it recognises.\n\n  XMASH uses the XPK Compression libraries for MAXIUM compatability and\n  compression.  This leaves XMASH free to concentrate on the user interface\n  and error handling instead of getting caught up in complicated comression\n  algorithms,  it leaves this the xpkxxxx libraries.\n\n@EndNode\n\n@Node Requirements "Requirements"\n\n  Requirements\n  ============\n\n  *  An Amiga! :-)\n\n  *  The XPK Compression libraries installed (See @{"Installation" link installation})\n\n  *  Half A Brain!\n\n@EndNode\n\n@Node Installation "Installation"\n\n  Installation\n  ============\n\n  To install XMash just make sure you have xpkmaster.library in libs:\n  and some compressor libraries in Libs:Compressors (preferably\n  XPKNUKE,FAST,SHRI and HFMN)  XMash defaults to using XPKSHRI.library as\n  this provides the best compresion ratio (but is a little slow!)\n\n  If use NUKE compressor you wont even notice XMash compressing as it''s\n  SOOOO fast (but files are larger than SHRI)\n\n  Next you need to copy XMASH somewhere in your path,  I prefer SYS:Archivers\n  but C: will do for most.\n\n  >>> XMASH NOW COMES WITH A NICE SCRIPT TO INSTALL SOME LIB FOR YOU <<<\n\n@EndNode\n\n@Node Usage "Usage"\n\n  Usage\n  =====\n\n  oh shit, I wish i didn''t have to type this bit in.....\n\n  Xmash has a wealth of options avaliable, these are as follows\n\n  READ=R/K,WRITE=W/K,FROM=TO/K,LOW=L/N,HIGH=H/N,TEXT=BANNER/K\n  TEST=T/K,APPEND/S,ADDTEXT/K,DESCRIBE=ADDDESC/K\n  DESCRIPTIONTEXT=DT/K,COMPRESSOR=MODE/K,TRACKINC/K/N,EXTRACT/K\n  QUIET/S,FIRST/S,DEVICE/K,TRACKS/K\n\n  Here''s each parameter in more detail.\n\n  key to symbols (dont include *ANY* symbols on the command line!)\n\n   |      alternatives specify only one. (EG fred|sid|barney)\n   []     optional parameter (see defaults.) [help|nohelp]\n   <>     type of object (E.G.  <Filename>)\n   <nn>   number\n\n  Everything else is as it is written.\n\n  Note:\n    Even tho I showed you a 2.04 style\n    usage template you cant use the ''='' (equals) sign is the parameters (you\n    must seperate parameters by the '' '' space character)\n\n\n  @{"Compressing A Disk To A File" link compressing}\n\n  @{"How to write a compressed file back to a disk" link writing}\n\n  @{"How to add a text file/banner/advert to a .XMS file" link addingtext}\n\n  @{"How to add a file description to a .XMS file" link addingdesc}\n\n  @{"How to extract a file description from a .XMS file" link extractdesc}\n\n  @{"How to test a .XMS file" link testing}\n\n  @{"Notes" link notes}\n\n@EndNode\n\n@Node Compressing "Compressing A Disk To A File"\n\n  Usage:\n\n    XMASH Read|r <Filename>[.xms] [From <dfx:>] [Low|L <nn>] [high|h <nn>]\n        [text|banner <textfilename>] [descriptiontext|dt <descriptionfilename>]\n        [compressor|Mode <compressor library>[.<nnn>]] [append] [trackinc <nn>]\n        [Device devicename] [Quiet]\n\n  Simple Example:\n\n    XMASH Read UL:NewFile.XMS From DF2: Low 0 High 39 Text BBS:BBSaddvert\n          DT FileDescs:NewFile.DIZ Mode FAST.100 Trackinc 10\n\n  Parameters:\n\n    <Filename>[.xms]\n\n          The name of the compressed file to save data in (you may\n          add the .XMS if you want, but if you dont XMASH will add it\n          to the end of the filename.\n          E.G. dh0:archived_stuff/cooldemo.xms\n\n    [From <dfx:>]\n\n          Uses specified drive to read disk from. Defaults to DF0:\n          (replace x with a unit number)\n          E.G. From DF1:\n\n    [Low|L <nn>]\n\n          Start Reading the disk from CYLINDER <nn>\n          where <nn> is from 00 to 79\n          E.G. Low 20\n\n    [High|H <nn>]\n\n          Stop Reading the disk at CYLINDER <nn>\n          where <nn> is from 00 to 79\n          E.G. High 50\n\n    [Text|Banner <textfilename>\n\n          Add a text file to the compressed file that will\n          be displayed when you unpack it.\n          (Note: the text file MUST be smaller than half your availiable\n          memory, so you *CAN* do really long text files if you want to!)\n          (note2: currently I''ve not made a way of removing text files\n          from an archive, but if you programmers out there want to make\n          a program that does then see the FileFormat.doc file included\n          with this program..)\n\n          E.G. Text bbs:bbsadd.ansi\n\n    [DescriptionText|DT <descriptionfilename>]\n\n          Add a file description to the file,  this is mainly used in BBS\n          systems.  Example usage of a file description is when you\n          upload a file to the BBS youwont have to sit there typing\n          in a file description, you can write the description Off-Line!\n          (see, Xmash has saved you money already!)\n          E.G. DT FileDescripts:Demo.desc\n\n    [Compressor|Mode <Compressor Library>[.<nnn>]]\n\n          This is the clever bit that lets you specify what xpk compressor\n          library to use.  The optional number specifies the compression\n          level to use (.100 = best, .000 = worst)\n          Only specify the 4 digits of the compressor library, so if you\n          wanted to use xpkNUKE.library you would use Compressor NUKE\n          or Mode NUKE.100\n          (compressors that encrypt data are NOT supported (yet!))\n\n    [Append]\n\n          This lets you add more tracks to an already compressed file\n          Typical usage could be to append a patch onto an existing file\n          (note: if you want to you can use a different compressor library\n          to the one that''s used in the origonal file, so if you want\n          you could compress a disk with each track being compressed\n          with a different compressor.)\n          (note2: you can add more textfiles like this!!)\n\n    [Trackinc <nn>]\n\n          This paramter has got to be the single most important parameter\n          of this program.  It tells Xmash how many tracks to read into\n          memory before it compresses them,  the more tracks the better\n          they get compressed, but the it takes longer to compress and\n          uses more memory ((5632 * Trackinc) * 2 + a margin)\n          This defaults to 10 tracks. (5 cylinders)\n          (note: this is Tracks not Cylinders. There are 160 tracks to\n          a standard 880K Amiga disk, Cylinders * 2 Surfaces!)\n          E.G.  Trackinc 20\n\n    [Tracks <tracklist>]\n\n          This option tells XMASH to pack a list of tracks specified by\n          tracklist.\n\n          The format of the tracklist is thus:  tracknumber[-tracknumber],...\n\n          E.G.\n\n          Tracks 5,32-35,70,72-79\n\n          The above example would cause XMASH to pack track 5, followed by\n          tracks 32 to 35 then track 70 then tracks 72-79\n\n          This feature is great when you want to make fix''s and trainer files!\n\n          (Thanks go to MuB/LSD for this cool idea!)\n\n    [Device devicename]\n\n          This lets you use any device that supports the standard\n          trackdisk.device commands.  This is usefull when you use things like\n          TEQDISK which lets you read and write to files on your hard disk\n          as if they werestandard floppy disks.  Note:  at present XMASH\n          wont get the ACTUAL devicename (E.G. trackdisk.device) from the\n          actual mounted device (E.G. DF0:) you must specify the mounted\n          device''s name using the FROM/TO parameter.\n\n          Also be aware that the device name IS case sensitive (as as any\n          device/library name on the Amiga!)\n\n          E.G.  Xmash Read Ram:TEST from TE0: device TEQDISK.device\n\n          (Again thanks to MuB/LSD for this idea!)\n\n@endnode\n\n@Node writing "How to write a compressed file back to a disk"\n\n  Usage:\n\n    XMASH Write|W <Filename>[.xms] [To <dfx:>] [Low|L <nn>] [high|h <nn>]\n          [Device devicename] [Quiet]\n\n  Simple Example:\n\n    XMASH Write DL:NewFile.XMS To DF1:\n\n  Parameters:\n\n    [To <dfx:>]\n\n          Uncompresses the compressed file to specified drive\n          E.G.  To DF2:\n\n    All other parameters as per Compressing a disk.\n\n  Notes:\n\n    Low and High will only write blocks of tracks (specified by\n    trackinc when you compress the disk.)  E.G.  say you packed the disk\n    with trackinc set to 20 (thats 10 cylinders per crunched block of data)\n    and you wanted to just unpack Cylinder 2 then you would use the command\n    XMASH write <file> Low 2 High 2\n    If you did this you would notice that Cylinders 0-9 get written to\n    the disk,  this is because they are all in the same block and this\n    version of XMASH wont split up blocks of crunched data into single\n    cylinders (although if people want it to then I may implement it)\n\n@EndNode\n\n@Node AddingText "How to add a text file/banner/advert to a .XMS file"\n\n  Usage:\n\n    XMASH AddText <Filename>[.xms] Text|Banner <TextFilename>\n\n  Simple Example:\n\n    XMASH AddText UpLoad:NewDemo.XMS Text BBS:BBSAdvert\n\n  Parameters:\n\n    All other parameters as per compressing a disk\n\n@EndNode\n\n@Node AddingDesc "How to add a file description to a .XMS file"\n\n  Usage:\n\n    XMASH AddDesc|Describe <Filename>[.xms]\n          DT|DescriptionText <DesciptonFilename>\n\n  Simple Example:\n\n    XMASH Describe UpLoad:NewDemo.XMS DT FileDescs:NewDemo.DIZ\n\n  Parameters:\n\n    All parameters as per compressing a disk\n\n@EndNode\n\n\n@Node ExtractDesc "How to extract a file description from a .XMS file"\n\n  Usage:\n\n    XMASH Extract <Filename>[.xms]\n          DT|DescriptionText <DesciptonFilename> [First]\n\n  Simple Example:\n\n    XMASH Extract UpLoad:NewDemo.XMS DT FileDescs:NewDemo.DIZ\n\n  Parameters:\n\n    Extract <filename>[.xms]\n\n          This parameter tells XMash to extract any file descriptions in the\n          XMS file to the file <DescriptionFilename>\n\n    First\n\n          This parameter tells Xmash to Keep the first file description it\n          finds and exit.   Normally Xmash will search the whole .XMS file\n          extracting all the descriptions it finds to the\n          <DescriptionFilename> file overwriting it every time it comes\n          accross another description.  It does this because you may append\n          new file descriptions to the end of a .XMS file.\n\n    All parameters as per compressing a disk\n\n@EndNode\n\n@Node Testing "How to test a .XMS file"\n\n  Usage:\n\n    XMASH test <Filename>[.xms]\n\n  Simple Example:\n\n    XMASH test BBS:Playpen/Newfile.DMS\n\n  Parameters:\n\n    None\n\n@EndNode\n\n\n@Node Notes "Notes"\n\n  XMASH searches for compressors when you run it so that if it has\n  a problem crunching anything it''ll keep trying a different compressor\n  until it crunches the data correctly!\n\n@EndNode\n\n@Node Sysop "Sysop''s Notes!"\n\n  Sysop''s Notes!\n  ==============\n\n  If you are using /X then....\n\n  Add the following tooltypes to your bbs:doors/fileid/File_ID.info\n\n  XMS_EX=c:XMSExtract %WFILE_ID.DIZ %P\n  XMS_AD=c:XMSDescribe %WFILE_ID.DIZ %P\n\n  this will allow extracting and adding of file_id.diz files to xmash files...\n\n  Also copy the supplied file in the FCheck directory to your BBS:FCheck\n  directory to allow checking of XMASH files..\n\n\n@EndNode\n\n@Node History "History"\n\n  History\n  =======\n\n  V1.0 (07/Feb/94)\n  ================\n  * First Release\n\n\n  V1.1\n  ================\n  * Corrected Minor bug in that it didn''t recognise filenames with lowercase\n    extensions is you type the whole filename in and not just the part before\n    the extension...\n\n    So  XMASH TEST testme.xms  wouldnt work, but XMASH TEST testme would :-)\n\n    weird huh ?\n\n\n  * Also fixed a little bug that cropped up if you pressed ESC to cancel a\n    read it would leave a little 3 byte file behind.  Not any more!\n\n  * Saw a nice little program called XMASHGUI, now included with XMASH\n\n    (hey, nice program m8, send me the source and i''ll do a proper GUI\n    Version.. :-)\n\n@EndNode\n\n@Node Greets "Greets"\n\n  Greets\n  ======\n\n  Cool Greets go to the following d00ds!\n\n  Cruise!               Lazzer              Huk\n  Yankee Rose           Slave               Apprentice\n  Dr Zero               Fish                Mub\n  Pazza                 Zandor              Black Beard\n  Toyax                 Hood                Pilgrim\n  The Joker             Shredder            Flat Lined\n  Mad Max               Cortex              Chem\n  Iceberg               Zion                Gt One\n  Dr.Lektor             Sasha               Astropath\n  Hawker                Axen                Oedipus\n\n  and all other d00ds that I''ve met on BBS''s and at Dtl''93!\n\n  Not Forgetting all other Perspex, LSD and Radiance Doods\n  that I''ve not mentioned here!\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',138492,4,0,NULL,NULL,'xmash11','scan',1780048843);
INSERT INTO door_catalog VALUES('xnd_wall','XND-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XND-WALL.LHA','XonderWall','XIM','.------------------------------------------.',NULL,'Xonder!','XND','|             XONDERWALL 1.oo              | |------------------------------------------| |  Ami Express-wall by Xonder!             |',replace('.------------------------------------------.\n|             XONDERWALL 1.oo              |\n|------------------------------------------|\n|  Ami Express-wall by Xonder!             |\n|                                          |\n|  Features: Possibility to disable users  |\n|            U can download all wallmsg''s  |\n`------------------------------------------''\n','\n',char(10)),'docs.txt',replace('\n             XONDERWALL 1.oo by XONDER\n------------------------------------------------------------------------------\n\nFeatures:\n---------\n\nNothing exceptional really but here they are:\n\n· possibility to disable unwanted users from writing on the wall\n\n· you can be anonymous if you want!   (WOW!) :)\n\n· possibility to download a textfile with all messages ever written on the wall\n\nThat''s about it I guess! :) (But what the F*CK, this is my first door) :)\n\nRequirements:\n-------------\n\n· An Amiga! (No kidding!)\n\n· AmiExpress (don''t know what versions it works on) :) \n\nIt has only been tested with Express 4.8\n\nInstallation:\n-------------\n\nJust copy the files to there proper places.\nMake sure you have doors: assigned to the correct place too.\n\nUsage:\n------\n\nto start the wall just type ''wall'' at the prompt.\n\nIf you want it in the bbs-logon then add the line:\n-------------------------------------<CUT>-----------------------------------\n~CC_WALL \n-------------------------------------<CUT>-----------------------------------\ninto your logon.txt or logon.txt.gr located inte the NODEx drawer\ndon''t forget to add either a trailing ''|'' or to push <return> after\n\nIf you want to disable users from writing on the wall, just enter the users\nhandle who you''d like to disable in the file ''notwanted.txt''\nOne user per line, CASE SENSITIVE..... You can have a maximum of 20 users \ndisabled. That ought to be enough for anybody! :)  \n\nIf you push ''d'' when your''e asked whether or not you want to write on the wall\nthen you are able to download a textfile with everything ever written on the \nwall in it! Unless you haven''t deleted the file ''alltimewall.txt'' of course :)\nA current_time-stamp of when the user wrote the message will be put there too.\n\nHistory:\n--------\n\n1.oo - First & probably only released version...\n\nFuture:\n-------\n\nNONE! :) (PROBABLY)\n\nGreetings:\n----------\n\n· Mayhem, for some help (Just a little) :)\n\n· No way, for some help making the door pc-compatible.....\n\n------------------------------------------------------------------------------\n','\n',char(10)),NULL,NULL,35027,5,0,NULL,NULL,'xnd_wall_xonderwall','scan',1780048843);
INSERT INTO door_catalog VALUES('xnetxim','XNETXIM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XNETXIM.LHA',NULL,'XIM','__  __         __  __________',NULL,'NetOnline!',NULL,'/  \/ / ____   /  \/ __/_  __/ SHOWNET / />  < /___/  / / / __/ / /      -&- /_//_/\_\      /_/_/___/ /_/     ADDNET',replace('   __  __         __  __________            \n  /  \/ / ____   /  \/ __/_  __/ SHOWNET    \n / />  < /___/  / / / __/ / /      -&-      \n/_//_/\_\      /_/_/___/ /_/     ADDNET     \n; Shows "NETNODES.AXN" To The User          \n; Users Can Add Their "NetNodes"            \n; Used By NetOnline!                   -JAF-\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 12-22-17  TIME: 18:53:35  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,21309,4,0,NULL,NULL,NULL,'scan',1780048843);
INSERT INTO door_catalog VALUES('xplxu100','XPLXU100.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/XPLXU100.LZX',NULL,'XIM','XPL_MATopUL100',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',15360,0,0,NULL,NULL,'xplxu100','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr10','XPSTR10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR10.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'O F * Q U A R T E X * pRESENTs',replace('                 R E b E L\n \n                    O F\n \n             * Q U A R T E X *\n \n                  pRESENTs\n \n             /XPRESS STRIP 1.0\n \n (The one you''ve all been badgering me for)\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[           t O O L T Y P E S           ]" LINK tooltypes}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                       vERSiON 1.0 - rELEASED 11/09/95\n\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.add.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n\nThis utility does require WB2 or higher, but anyone these days who is\nrunning an Amiga (or even worse a BBS) without WB2 must be pretty pathetic\nanyway.\n@ENDNODE\n\n@NODE tooltypes "Tooltypes"\n\n                            [ t O O L T Y P E S ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon can contain the following tooltypes to configure\ncertain aspects of this program\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  ADDLIST=<filename>	A file containing a list of files (full path) which\n			will be added to the archive.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters which will cause the file\n			to be removed from the archive. If not present then\n			illegal character stripping will be disabled.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  RANDOMADD=<filename>	Full path to the add to be used for random adds. This\n			tooltype if present enables random adding.\n			[OPTIONAL]\n\n  RANDOMCOUNT=<number>	Number of random adds to be appended to the archive.\n			The filenames will be chosen at random from the\n			characters listed in RANDOMCHARS between 1 and 10\n			characters long.\n			[REQUIRED IF RANDOMADD IS PRESENT]\n\n  RANDOMCHARS=<string>	Characters to be used to generate the random filenames\n			for random adds. If not present the default characters\n			are A-Z and 0-9.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent analysis routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, and it will test each add in turn to make\n			sure it is an add before stripping it. This is not\n			necessary in many cases but the option is available\n			to reduce the risk of the routines stripping a file\n			which is not an addy.\n			[OPTIONAL]\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\n\n    v0.xx	Beta test versions distributed to people on request\n\n    v1.00	First public release version\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned are COBRA, DARK ANGEL\n  DUSTY, ORDYNE, rUFF sTøNES, SARGE and ZOLTRIX. Thanks guys!!\n\n  Next on the list is some personal messages\n\n   ZOLTRIX - code on dude ;)\n\n   JR. - subversion sux hahahah\n\n   DARK ANGEL - drunk again ?\n\n   DUSTY - phew this has saved me hours of work ;)\n\n   ORDYNE - Wow thats what i call power\n\n   DEMONS - great to hear from you again..\n\n   CRuISE - where ya bin?\n\n   SASHA - this one works :)\n\n   RAMRAIDER - voyager rocks!\n\n   ACE- Addie attack ! arrggg!\n\n  Also a mention must go to the following dudes:\n\n   Pixie, Chelsea, Scouser, Deadlight, Butcher, Mr. Dalvin, Dark Angel,\n   Sarge, Cyborg, Dusty, Icon, T-Force, Noddy, Zoltrix, Suzuki, rUFF Stones,\n   Frosty, Codeman, Nobby, T-Man, Strobe, Zorro, JR., Demons, Avenger, \n   Collector, Iceman, Cruise, ads/pdx, iggy, cat, white stallion, gaz p, \n   zandor/sr, sasha, ace, texas, playboy, stu, deature, cheetah, prolix, \n   indigo, pingu, ordyne, |>|s<()r|>|/\, Abrasax, Daz, Tonto, Chill and\n   the undertaker\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support....	unlikely unless i get detailed information\n			on the LZX file format\n\n	Time/Date Stamping....	A possible update at a later time to\n				allow time/date/uploader name etc to\n				be inserted into the add.\n\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests). If you know how to contact me then you can consider\n  yourself kewl enough to deserve a private registered version, if not then\n  forget all about it :)\n\n  The list of registered users currently stands as:\n\n		REbEL/QTX (me of course)\n		DARK ANGEL\n		DUSTY\n		OrdYne\n		rUFF sTøNES\n		SARGE\n		ZOLTRIX\n\n\n  Ask any of these about this kewl production.\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne/NVX (thx dude!)\n\n  Beta Testers - COBRA\n		 DARK ANGEL\n		 DUSTY\n		 OrdYne\n		 rUFF sTøNES\n		 SARGE\n		 ZOLTRIX\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',11976,4,0,NULL,NULL,'xpstr10','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr102','XPSTR102.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR102.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'\_ | _/. _ Y .   /___). ___). ___) .-----. / .  //  __|/ |_/ _)_|___ .\___ .\ |v1.02| \__|_\ .|::|__|:|____)_____/_____/ `-----''',replace(' ___._______ _____________________\n \_ | _/. _ Y .   /___). ___). ___) .-----.\n / .  //  __|/ |_/ _)_|___ .\___ .\ |v1.02|\n \__|_\ .|::|__|:|____)_____/_____/ `-----''\n +-----\_|--------------------------------+\n | __/\__ .-----------------------. __/\__|\n : \ Oo / |A comprehensive LHA/LZH| \ oO /:\n : /_ ._\ |stripper. Now featuring| /_. _\:\n : ¯¯\/¯¯ |new FAST ADD mode.     | ¯¯\/¯¯:\n :        `-----------------------''       :\n `-[REBEL/QTX]-----------------[10.10.95]-''\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                                 vERSiON 1.02\n\n''Oh no here we go again.. with another load of reg''d versions to assemble ;)''\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.add.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon can contain the following tooltypes to configure\ncertain aspects of this program\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  ADDLIST=<filename>	A file containing a list of files (full path) which\n			will be added to the archive.\n			[OPTIONAL]\n\n  FASTADD=<filename>    An LHA/LZH file containing adds (or anything else)\n			Which will be appended to the file being checked.\n			This method of adding is very fast, due to the fact\n			that the files are already compressed within the\n			archive so there is no need to compress them into the\n			archive being tested. The one disadvantage of this\n			method is it is not possible to have random filenames.\n			Also you should be careful to make sure that the file\n			you are adding is an LHA/LZH archive, because this\n			program will simply proceed to tag it onto the lha/lzh\n			archive being tested, and you could easily end up with\n			a corrupted archive.\n			[OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARRACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  RANDOMADD=<filename>	Full path to the add to be used for random adds. This\n			tooltype if present enables random adding.\n			[OPTIONAL]\n\n  RANDOMCOUNT=<number>	Number of random adds to be appended to the archive.\n			The filenames will be chosen at random from the\n			characters listed in RANDOMCHARS between 1 and 10\n			characters long.\n			[REQUIRED IF RANDOMADD IS PRESENT]\n\n  RANDOMCHARS=<string>	Characters to be used to generate the random filenames\n			for random adds. If not present the default characters\n			are A-Z and 0-9.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type. This protectes the archive from having\n			important files removed from it. It also severaly\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure\n			[OPTIONAL]\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne/NVX\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specificly.\n			[OPTIONAL]\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are seperated by one or more spaces.Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysys routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\nVersions 0.xx\n\nBeta test versions distributed to people on request\n\n\nVersion 1.00\n\nFirst public release version\n\n11/09/95\n\n\nVersion 1.01\n\nCRC Stripper, Bulletin and second output styles added.\n\n22/09/95\n\n\nVersion 1.02\n\nBug in the MAXLINES tooltype fixed, this caused random crashes on some\nmachines and also adds were never stripped with this option enabled.\nFASTADD option added. The program now returns a error value of -1 if an\nerror occurred. This will be of use to NASTYDUPECHECK users.\nBug in the bulletin output fixed. If the filename of an add was long enough\nthe output of the bulletin would be skewed (it may be necessary to delete\nyour lhastripper.topdata file if this bug has affected you).\n\n10/10/95\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned are DARK ANGEL,\n  DUSTY, ORDYNE, rUFF sTøNES, SARGE and ZOLTRIX. Thanks guys!! Also a special\n  thanks must go to MDR who has returned to make my life hell... oops i mean\n  to find lots of bugs ;)\n\n  Also a mention must go to the following dudes:\n\n   Pixie, Chelsea, Scouser, Deadlight, Butcher, Mr. Dalvin, Dark Angel,\n   Sarge, Cyborg, Dusty, Icon, T-Force, Noddy, Zoltrix, Suzuki, rUFF Stones,\n   Frosty, Codeman, Nobby, T-Man, Strobe, Zorro, JR., Demons, Avenger, \n   Collector, Iceman, Cruise, ads/pdx, iggy, cat, white stallion, gaz p, \n   zandor/sr, sasha, ace, texas, playboy, stu, deature, cheetah, prolix, \n   indigo, pingu, ordyne, |>|s<()r|>|/\, Abrasax, Daz, Tonto, Chill and\n   the undertaker.\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support....	unlikely unless i get detailed information\n			on the LZX file format.\n\n	Time/Date Stamping....	A possible update at a later time to\n				allow time/date/uploader name etc to\n				be inserted into the add.\n\n	GUI Interface... Gui program to maintain the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests). If you know how to contact me then you can consider\n  yourself kewl enough to deserve a private registered version, if not then\n  forget all about it :) You can also try contacting any of the previously\n  mentioned beta testers.\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne/NVX (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Diz Design	- Chill/976 Ev!L/Data Division\n\n  Beta Testers - DARK ANGEL\n		 DUSTY\n		 OrdYne\n		 rUFF sTøNES\n		 SARGE\n		 ZOLTRIX\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',21177,4,0,NULL,NULL,'xpstr102','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr11','XPSTR11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR11.LHA','LHAStripper','XIM','LE-win5-96.exe',NULL,NULL,NULL,'O F * Q U A R T E X * pRESENTs',replace('                 R E b E L\n \n                    O F\n \n             * Q U A R T E X *\n \n                  pRESENTs\n \n             /XPRESS STRIP 1.01\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                                 vERSiON 1.01\n\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.add.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon can contain the following tooltypes to configure\ncertain aspects of this program\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  ADDLIST=<filename>	A file containing a list of files (full path) which\n			will be added to the archive.\n			[OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARRACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  RANDOMADD=<filename>	Full path to the add to be used for random adds. This\n			tooltype if present enables random adding.\n			[OPTIONAL]\n\n  RANDOMCOUNT=<number>	Number of random adds to be appended to the archive.\n			The filenames will be chosen at random from the\n			characters listed in RANDOMCHARS between 1 and 10\n			characters long.\n			[REQUIRED IF RANDOMADD IS PRESENT]\n\n  RANDOMCHARS=<string>	Characters to be used to generate the random filenames\n			for random adds. If not present the default characters\n			are A-Z and 0-9.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type. This protectes the archive from having\n			important files removed from it. It also severaly\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure\n			[OPTIONAL]\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne/NVX\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specifically.\n			[OPTIONAL]\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are seperated by one or more spaces.Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysys routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\n\n    v0.xx	Beta test versions distributed to people on request\n\n    v1.00	First public release version (11/09/95)\n\n    v1.01	CRC Stripper and Bulletin and second output style added\n		(22/09/95)\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned are DARK ANGEL,\n  DUSTY, ORDYNE, rUFF sTøNES, SARGE and ZOLTRIX. Thanks guys!!\n\n  Also a mention must go to the following dudes:\n\n   Pixie, Chelsea, Scouser, Deadlight, Butcher, Mr. Dalvin, Dark Angel,\n   Sarge, Cyborg, Dusty, Icon, T-Force, Noddy, Zoltrix, Suzuki, rUFF Stones,\n   Frosty, Codeman, Nobby, T-Man, Strobe, Zorro, JR., Demons, Avenger, \n   Collector, Iceman, Cruise, ads/pdx, iggy, cat, white stallion, gaz p, \n   zandor/sr, sasha, ace, texas, playboy, stu, deature, cheetah, prolix, \n   indigo, pingu, ordyne, |>|s<()r|>|/\, Abrasax, Daz, Tonto, Chill and\n   the undertaker.\n\n  And a final mention to crew^one/myth.... thanks for the chat m8... do it\n  again sometime... only it cost me a fortune hehe..\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support....	unlikely unless i get detailed information\n			on the LZX file format.\n\n	Time/Date Stamping....	A possible update at a later time to\n				allow time/date/uploader name etc to\n				be inserted into the add.\n\n	GUI Interface... Gui program to maintaint the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests). If you know how to contact me then you can consider\n  yourself kewl enough to deserve a private registered version, if not then\n  forget all about it :) You can also try contacting any of the previously\n  mentioned beta testers.\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne/NVX (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Beta Testers - DARK ANGEL\n		 DUSTY\n		 OrdYne\n		 rUFF sTøNES\n		 SARGE\n		 ZOLTRIX\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',22429,5,0,NULL,NULL,'xpstr11','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr200','XPSTR200.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR200.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'\_ | _/. _ Y .   /___). ___). ___) .-----. / .  //  __|/ |_/ _)_|___ .\___ .\ |v2.00| \__|_\ .|::|__|:|____)_____/_____/ `-----''',replace(' ___._______ _____________________\n \_ | _/. _ Y .   /___). ___). ___) .-----.\n / .  //  __|/ |_/ _)_|___ .\___ .\ |v2.00|\n \__|_\ .|::|__|:|____)_____/_____/ `-----''\n +-----\_|--------------------------------+\n : __/\__ .-----------------------. __/\__:\n | \ Oo / |A Comprehensive LHA/LZH| \ oO /|\n : /_ ._\ |Stripper & Adder For /X| /_. _\:\n : ¯¯\/¯¯ | Lots New Since v1.02  | ¯¯\/¯¯:\n :        `-----------------------''       :\n `-[REbEL/QTX]-----------------[30.12.95]-''\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                            vERSiON 2.00 (30/12/95)\n\n''Oh no here we go again.. with another load of reg''d versions to assemble ;)''\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.list.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon contains tooltypes to configure many aspects\nof this program.\n\n\n            @{"STRIPPING CONFIGURATION" LINK stripconfig}\n\n            @{"ADDING CONFIGURATION" LINK addconfig}\n\n            @{"MISCELLEANOUS CONFIGURATION" LINK miscconfig}\n\n@ENDNODE\n\n@NODE stripconfig "Stripping Configuration"\n\n               [ S T R I P P I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the stripping facilities of the program. If these are set\nup well, you can obtain very impressive results from this stripper.\n\n\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARRACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type. This protectes the archive from having\n			important files removed from it. It also severaly\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure\n			[OPTIONAL]\n\n  DUMP=<filename>       A feature where any files deleted from an archive are\n                        appended to an lha file of the given filename. This\n                        will slow down the checker somewhat but does ensure\n                        that any files that are removed that shouldn''t have\n                        been are not lost forever. You should keep tabs on\n                        this file because it will soon grow to be quite\n                        large. When using backlog stripping, files removed\n                        due to them being present in the backlog list will\n                        not be copied to the dump file. This will help to\n                        reduce replication of the same files being present\n                        in the dump file over and over again.\n                        [OPTIONAL]\n\n@ENDNODE\n\n@NODE addconfig "Adding Configuration"\n\n                  [ A D D I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the adding facilities of the program. These can be set up\nto add a maximum of 99 files to every archive. These tooltypes except the\nFASTADD are followed by a number from 1 to 99, for each file you should\nspecify these tooltypes once. ie SRCNAME.1, DESTNAME.1, RANDOMCHARS.1 etc.\nthen for the next file SRCNAME.2, DESTNAME.2 etc..\n\nFinally there is the FASTADD which is a totally seperate (very fast) method\nof adding files which is explained below.\n\n\n\n  SRCNAME.x=<filename>  This is the tooltype which enables the adding part\n                        of the checker. You can add upto 99 different files\n                        by specifying ''SRCNAME.1'' through to ''SRCNAME.99''.\n                        Each of the following tooltypes should run in a\n                        similar manner, starting at 1, upto 99. This tooltype\n                        specifies the full path the file file to be added to\n                        the archive.\n                        [OPTIONAL]\n\n  DESTNAME.x=<string>   This tooltype defines the name that the file is added\n                        to the archive is called. It may be a path containing\n                        subdirectories (so HERE/IS/MY/ADD.TXT is fine). This\n                        is required for each file to be added to the archive.\n                        The name can also contain ? symbols, each of which\n                        will be replaced with a random character (chosen from\n                        the list in the tooltype below or from the default\n                        list).\n                        [REQUIRED FOR EACH SRCNAME TOOLTYPE]\n\n  RANDOMCHARS.x=<string>This is the list of random characters used to replace\n                        any ? symbols in the destination filename for adds.\n                        If this tooltype is not present the list defaults to\n                        A-Z and 0-9.\n                        [OPTIONAL]\n\n  ANAGRAM.x             This tooltype will specify that each letter from the\n                        random character string can only be used once. This\n                        means you can create anagrams of strings. If you\n                        specify ????? as the destination name, and HELLO as\n                        the random character string, then using this option\n                        you will get random anagrams of the word HELLO with\n                        each character used once only.\n                        [OPTIONAL]\n\n  DESTLIST.x=<filename> This can be used as an alternative to specifying\n                        the destination filename in DESTNAME.x above. This\n                        allows you to have a file containing a list of\n                        possible destination names and one will be chosen\n                        at random. DESTNAME.x will always take priority over\n                        this option and if you specify both, the string in\n                        DESTNAME.x will be used. Notice that the filenames in\n                        this list are processed in the same manner as those\n                        from DESTNAME.x meaning you can still use ? as a\n                        random character, and directory names are allowed.\n                        [OPTIONAL]\n\n  NOSTAMP.x             A tooltype which prevents timestamping. If this\n                        tooltype is omitted, certain codes (listed below)\n                        will be replaced with the current time and date.\n                        If you are using non text files as adds (ie pictures\n                        or executables etc) then you will want to make sure\n                        that any occurances of these codes present in the\n                        non text files adds are not replaced with the time\n                        and date.\n                        [OPTIONAL]\n\n  FASTADD=<filename>    An LHA/LZH file containing adds (or anything else)\n			Which will be appended to the file being checked.\n			This method of adding is very fast, due to the fact\n			that the files are already compressed within the\n			archive so there is no need to compress them into the\n			archive being tested. The one disadvantage of this\n			method is it is not possible to have random filenames\n                        or to have the control codes for timestamping. You\n			should be careful to make sure that the file you are\n			is actually an LHA/LZH archive, because this program\n			will simply proceed to tag it onto the lha/lzh\n			archive being tested, and you could easily end up with\n			a corrupted archive.\n			[OPTIONAL]\n\n\nTimestamp facilities are also available. The following codes present in any\nadded file (except FASTADD archives) will be replaced with the current date\nand time in the given format:\n\n\n        DD/MM/YY  - replaced by the date in UK format (ie 25/12/95)\n\n        DD-MMM-YY - replaced by the date in system format (ie 25-Dec-95)\n\n        HH:MM:SS  - replaced by the time including seconds (ie 23:18:56)\n\n        HH:MM     - replaced by the time without seconds (ie 23:18)\n\n\nIMPORTANT\n\n 1 - Read the note on disabling timestamping above if you are using\n     non text adds (ie GIF/IFF/EXE).\n\n 2 - The above codes are case sensitive, dd/mm/yy will not do - they must\n     be EXACTLY as shown above.\n\n@ENDNODE\n\n@NODE miscconfig "Miscelleanous Configuration"\n\n           [ M I S C E L L E A N O U S   C O N F I G U R A T I O N ]\n\n\nThese tooltypes alter various other functions of the program related\nto the output etc.\n\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  SHOWKILLED            This tooltype only takes effect when used with the\n                        QUIET option above. This causes the stripper to\n                        still list the files removed from the archive but\n                        not to list the whole contents.\n                        [OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne/NVX\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specificly.\n			[OPTIONAL]\n\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are seperated by one or more spaces.Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysys routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\nVersions 0.xx\n\nBeta test versions distributed to people on request\n\n\nVersion 1.00\n\nFirst public release version\n\n11/09/95\n\n\nVersion 1.01\n\nCRC Stripper, Bulletin and second output styles added.\n\n22/09/95\n\n\nVersion 1.02\n\nBug in the MAXLINES tooltype fixed, this caused random crashes on some\nmachines and also adds were never stripped with this option enabled.\n\nFASTADD option added.\n\nThe program now returns a error value of -1 if an\nerror occurred. This will be of use to NASTYDUPECHECK users.\n\nBug in the bulletin output fixed. If the filename of an add was long enough\nthe output of the bulletin would be skewed (it may be necessary to delete\nyour lhastripper.topdata file if this bug has affected you).\n\n10/10/95\n\n\nVersion 1.03ß\n\nBeta versions distributed to various people.\n\nSeveral small (non-fatal) bugs have been fixed. The top 10 list on the\nbulletin was sometimes getting disordered. Adding was listed as being OFF\non the output when only FASTADD mode was enabled.\n\n??/12/95\n\n\nVersion 2.00\n\nMajor overhaul in the add routines. They now work completely differently\nand are far more flexible than before.\n\nTimestamp facilities have been implemented.\n\n30/12/95\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned know who they are\n\n  Also a quick hello must go to the following dudes:\n\n   Pixie, Chelsea, Scouser, Deadlight, Butcher, Mr. Dalvin, Dark Angel,\n   Sarge, Cyborg, Epsilon, Icon, T-Force, Zoltrix, rUFF Stones, MDR\n   Codeman, Strobe, Zorro, JR., Demons, Avenger, Cruise, ads/pdx, iggy,\n   cat, white stallion, gaz p, zandor/sr, sasha, ace, deature, cheetah,\n   prolix, indigo, pingu, |>|s<()r|>|/\, Abrasax, Chill and the undertaker.\n\n  Special thanks to Cruise, Enzo and MDR for their help and suggestions for\n  improvements. Hope this update is to your liking.\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support..... unlikely unless i get detailed information\n			 on the LZX file format.\n\n	GUI Interface... Gui program to maintain the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests).\n\n  I can be contacted on many of the uks boards, also a few euro boards\n  (but dont expect a fast reply from these - its expensive calling europe)\n  i can also be emailed at [email removed]\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Diz Design	- Chill/976 Ev!L/Data Division\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',23031,2,0,NULL,NULL,'xpstr200','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr202','XPSTR202.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR202.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'\_ | _/. _ Y .   /___). ___). ___) .-----. / .  //  __|/ |_/ _)_|___ .\___ .\ |v2.02| \__|_\ .|::|__|:|____)_____/_____/ `-----''',replace('___._______ _____________________\n\_ | _/. _ Y .   /___). ___). ___) .-----.\n/ .  //  __|/ |_/ _)_|___ .\___ .\ |v2.02|\n\__|_\ .|::|__|:|____)_____/_____/ `-----''\n+-----\_|--------------------------------+\n: __/\__ .-----------------------. __/\__:\n| \ Oo / |  The kewlest LHA/LZH  | \ oO /|\n: /_ ._\ |    stripper around    | /_. _\:\n: ¯¯\/¯¯ |    BUGFIXED UPDATE    | ¯¯\/¯¯:\n:        `-----------------------''       :\n`-[REbEL/QTX]-----------------[17.01.96]-''\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                            vERSiON 2.02 (17/01/96)\n\n''Oh no here we go again.. with another load of reg''d versions to assemble ;)''\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.list.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon contains tooltypes to configure many aspects\nof this program.\n\n\n            @{"STRIPPING CONFIGURATION" LINK stripconfig}\n\n            @{"ADDING CONFIGURATION" LINK addconfig}\n\n            @{"MISCELLEANOUS CONFIGURATION" LINK miscconfig}\n\n@ENDNODE\n\n@NODE stripconfig "Stripping Configuration"\n\n               [ S T R I P P I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the stripping facilities of the program. If these are set\nup well, you can obtain very impressive results from this stripper.\n\n\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARRACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type. This protectes the archive from having\n			important files removed from it. It also severaly\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure\n			[OPTIONAL]\n\n  DUMP=<filename>       A feature where any files deleted from an archive are\n                        appended to an lha file of the given filename. This\n                        will slow down the checker somewhat but does ensure\n                        that any files that are removed that shouldn''t have\n                        been are not lost forever. You should keep tabs on\n                        this file because it will soon grow to be quite\n                        large. When using backlog stripping, files removed\n                        due to them being present in the backlog list will\n                        not be copied to the dump file. This will help to\n                        reduce replication of the same files being present\n                        in the dump file over and over again.\n                        [OPTIONAL]\n\n@ENDNODE\n\n@NODE addconfig "Adding Configuration"\n\n                  [ A D D I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the adding facilities of the program. These can be set up\nto add a maximum of 99 files to every archive. These tooltypes except the\nFASTADD are followed by a number from 1 to 99, for each file you should\nspecify these tooltypes once. ie SRCNAME.1, DESTNAME.1, RANDOMCHARS.1 etc.\nthen for the next file SRCNAME.2, DESTNAME.2 etc..\n\nFinally there is the FASTADD which is a totally seperate (very fast) method\nof adding files which is explained below.\n\n\n\n  SRCNAME.x=<filename>  This is the tooltype which enables the adding part\n                        of the checker. You can add upto 99 different files\n                        by specifying ''SRCNAME.1'' through to ''SRCNAME.99''.\n                        Each of the following tooltypes should run in a\n                        similar manner, starting at 1, upto 99. This tooltype\n                        specifies the full path the file file to be added to\n                        the archive.\n                        [OPTIONAL]\n\n  DESTNAME.x=<string>   This tooltype defines the name that the file is added\n                        to the archive is called. It may be a path containing\n                        subdirectories (so HERE/IS/MY/ADD.TXT is fine). This\n                        is required for each file to be added to the archive.\n                        The name can also contain ? symbols, each of which\n                        will be replaced with a random character (chosen from\n                        the list in the tooltype below or from the default\n                        list).\n                        [REQUIRED FOR EACH SRCNAME TOOLTYPE]\n\n  RANDOMCHARS.x=<string>This is the list of random characters used to replace\n                        any ? symbols in the destination filename for adds.\n                        If this tooltype is not present the list defaults to\n                        A-Z and 0-9.\n                        [OPTIONAL]\n\n  ANAGRAM.x             This tooltype will specify that each letter from the\n                        random character string can only be used once. This\n                        means you can create anagrams of strings. If you\n                        specify ????? as the destination name, and HELLO as\n                        the random character string, then using this option\n                        you will get random anagrams of the word HELLO with\n                        each character used once only.\n                        [OPTIONAL]\n\n  DESTLIST.x=<filename> This can be used as an alternative to specifying\n                        the destination filename in DESTNAME.x above. This\n                        allows you to have a file containing a list of\n                        possible destination names and one will be chosen\n                        at random. DESTNAME.x will always take priority over\n                        this option and if you specify both, the string in\n                        DESTNAME.x will be used. Notice that the filenames in\n                        this list are processed in the same manner as those\n                        from DESTNAME.x meaning you can still use ? as a\n                        random character, and directory names are allowed.\n                        [OPTIONAL]\n\n  COMMENT.x=<string>    Set the filenote (filecomment) of the add to whatever\n                        is contained within this tooltype\n                        [OPTIONAL]\n\n  DELPROTECT.x          Protects the file add against deletion. This only\n                        prevents the file being deleted once it has been\n                        extracted from the archive, it doesnt stop you from\n                        deleting it from the archive.\n                        [OPTIONAL]\n\n\n  NOSTAMP.x             A tooltype which prevents timestamping. If this\n                        tooltype is omitted, certain codes (listed below)\n                        will be replaced with the current time and date.\n                        If you are using non text files as adds (ie pictures\n                        or executables etc) then you will want to make sure\n                        that any occurances of these codes present in the\n                        non text files adds are not replaced with the time\n                        and date.\n                        [OPTIONAL]\n\n  FASTADD=<filename>    An LHA/LZH file containing adds (or anything else)\n			Which will be appended to the file being checked.\n			This method of adding is very fast, due to the fact\n			that the files are already compressed within the\n			archive so there is no need to compress them into the\n			archive being tested. The one disadvantage of this\n			method is it is not possible to have random filenames\n                        or to have the control codes for timestamping. You\n			should be careful to make sure that the file you are\n			is actually an LHA/LZH archive, because this program\n			will simply proceed to tag it onto the lha/lzh\n			archive being tested, and you could easily end up with\n			a corrupted archive.\n			[OPTIONAL]\n\n\nTimestamp facilities are also available. The following codes present in any\nadded file (except FASTADD archives) will be replaced with the current date\nand time in the given format:\n\n\n        DD/MM/YY  - replaced by the date in UK format (ie 25/12/95)\n\n        DD-MMM-YY - replaced by the date in system format (ie 25-Dec-95)\n\n        HH:MM:SS  - replaced by the time including seconds (ie 23:18:56)\n\n        HH:MM     - replaced by the time without seconds (ie 23:18)\n\n\nIMPORTANT\n\n 1 - Read the note on disabling timestamping above if you are using\n     non text adds (ie GIF/IFF/EXE).\n\n 2 - The above codes are case sensitive, dd/mm/yy will not do - they must\n     be EXACTLY as shown above.\n\n@ENDNODE\n\n@NODE miscconfig "Miscelleanous Configuration"\n\n           [ M I S C E L L E A N O U S   C O N F I G U R A T I O N ]\n\n\nThese tooltypes alter various other functions of the program related\nto the output etc.\n\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  SHOWKILLED            This tooltype only takes effect when used with the\n                        QUIET option above. This causes the stripper to\n                        still list the files removed from the archive but\n                        not to list the whole contents.\n                        [OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specificly.\n			[OPTIONAL]\n\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are seperated by one or more spaces.Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysys routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\n@{B}Versions 0.xx@{UB}\n\nBeta test versions distributed to people on request\n\n\n@{B}Version 1.00@{UB}\n\nFirst public release version\n\n11/09/95\n\n\n@{B}Version 1.01@{UB}\n\nCRC Stripper, Bulletin and second output styles added.\n\n22/09/95\n\n\n@{B}Version 1.02@{UB}\n\nBug in the MAXLINES tooltype fixed, this caused random crashes on some\nmachines and also adds were never stripped with this option enabled.\n\nFASTADD option added.\n\nThe program now returns a error value of -1 if an\nerror occurred. This will be of use to NASTYDUPECHECK users.\n\nBug in the bulletin output fixed. If the filename of an add was long enough\nthe output of the bulletin would be skewed (it may be necessary to delete\nyour lhastripper.topdata file if this bug has affected you).\n\n10/10/95\n\n\n@{B}Version 1.03ß@{UB}\n\nBeta versions distributed to various people.\n\nSeveral small (non-fatal) bugs have been fixed. The top 10 list on the\nbulletin was sometimes getting disordered. Adding was listed as being OFF\non the output when only FASTADD mode was enabled.\n\n??/12/95\n\n\n@{B}Version 2.00@{UB}\n\nMajor overhaul in the add routines. They now work completely differently\nand are far more flexible than before.\n\nTimestamp facilities have been implemented.\n\n30/12/95\n\n\n@{B}Version 2.01@{UB} (Distributed to registered users on request only)\n\nNo testing is now done before stripping a file from the backlog list.\nThe individuality of the file crc coupled with its size means that no\nchecking is required, and the chances of it deleting a file by mistake are\nacceptable.\n\nA file present in the backlog list will now not be added to the dump file.\nThis saves repetition in the dump file.\n\nFiles are added to the backlog list even if they are already present, this\nstops them from getting ''PHASED OUT'' of the list.\n\nThe bulletin output routines no longer returns a value of -1\n(Thanks to SiRE for pointing out this problem)\n\n31/12/95\n\n\n@{B}Version 2.02@{UB}\n\nThe dump file was not closed properly under certain\ncircumstances. This caused the dump file to be corrupted.\n(Thanks to MDR for helping me find this one)\n\nTwo bugs in the new adding routines were causing the stripper to crash\non some machines.\n(Thanks to eNZO and SiRE for helping me sort this one)\n\nThe Top Ten wasnt updating (since v2.00) in the bulletin\n(Again thanks to MDR)\n\nTooltypes COMMENT.x and DELPROTECT.x added\n\nFixed a bug (another) in the new adding routines, causing it to lock\nrandomly when DESTLIST was used. (Thanks to eNZO and SARGE for helping\nme track this one down).\n\n17/01/96\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned know who they are\n\n  Also a quick hello must go to the following dudes:\n\n   Pixie, Chelsea, Scouser, Deadlight, Butcher, Mr. Dalvin, Dark Angel,\n   Sarge, Cyborg, Epsilon, Icon, T-Force, Zoltrix, rUFF Stones, MDR\n   Codeman, Strobe, Zorro, JR., Demons, Avenger, Cruise, ads/pdx, iggy,\n   cat, white stallion, gaz p, zandor/sr, sasha, ace, deature, cheetah,\n   prolix, indigo, pingu, |>|s<()r|>|/\, Abrasax, Chill and the undertaker.\n\n  Special thanks to Cruise, Enzo and MDR for their help and suggestions for\n  improvements... and anyone else who helped me with bug reports.... the\n  list of peeps who have helped is getting quite large now, so ill just say\n  THANKS without listing any names...\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support..... unlikely unless i get detailed information\n			 on the LZX file format.\n\n	GUI Interface... Gui program to maintain the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests).\n\n  I can be contacted on many of the uks boards, also a few euro boards\n  (but dont expect a fast reply from these - its expensive calling europe)\n  i can also be emailed at [email removed]\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Diz Design	- Chill/976 Ev!L/Data Division\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',38846,3,0,NULL,NULL,'xpstr202','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr203','XPSTR203.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR203.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'\_ | _/. _ Y .   /___). ___). ___) .-----. / .  //  __|/ |_/ _)_|___ .\___ .\ |v2.03| \__|_\ .|::|__|:|____)_____/_____/ `-----''',replace('___._______ _____________________\n\_ | _/. _ Y .   /___). ___). ___) .-----.\n/ .  //  __|/ |_/ _)_|___ .\___ .\ |v2.03|\n\__|_\ .|::|__|:|____)_____/_____/ `-----''\n+-----\_|--------------------------------+\n: __/\__ .-----------------------. __/\__:\n| \ Oo / |  The kewlest LHA/LZH  | \ oO /|\n: /_ ._\ |    stripper around    | /_. _\:\n: ¯¯\/¯¯ |MORE FEATURES THAN EVER| ¯¯\/¯¯:\n:        `-----------------------''       :\n`-[REbEL/QTX]-----------------[09.07.96]-''\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                            vERSiON 2.03 (09/07/96)\n\n''Oh no here we go again.. with another load of reg''d versions to assemble ;)''\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  hapily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.list.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon contains tooltypes to configure many aspects\nof this program.\n\n\n            @{"STRIPPING CONFIGURATION" LINK stripconfig}\n\n            @{"ADDING CONFIGURATION" LINK addconfig}\n\n            @{"MISCELLEANOUS CONFIGURATION" LINK miscconfig}\n\n@ENDNODE\n\n@NODE stripconfig "Stripping Configuration"\n\n               [ S T R I P P I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the stripping facilities of the program. If these are set\nup well, you can obtain very impressive results from this stripper.\n\n\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  HITLIST=<filename>    A file containing a list of key words which are used\n                        to determine whether the file being analysed is an\n                        advert or not. If any words that are listed in this\n                        HITLIST are in the file being tested, they will be\n                        counted, and if there are more than HITCOUNT the file\n                        is considered to be an advert. If this function is\n                        not used. files will simply be tested to ensure they\n                        are one of the following, TEXT, IFF ILBM, IFF ANIM,\n                        GIF, JPEG.\n                        [OPTIONAL]\n\n  HITCOUNT=<number>     The number of matching words from the HITLIST that\n                        need to be found to trigger stripping. (Defaults to 1)\n                        [OPTIONAL]\n\n  MISSLIST=<filename>   A file containing a list of key words which are used\n                        to make sure a file is left intact. This is useful\n                        to prevent ARexx and AmigaGuide, Docs etc. from\n                        being recognised as adverts. It works in exactly the\n                        same way as HITLIST/HITCOUNT.\n                        [OPTIONAL]\n\n  MISSCOUNT=<number>    The number of matches of words from the MISSLIST to\n                        prevent the file being stripped. (Defaults to 1)\n                        [OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARRACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type (and the hit and miss functions are executed\n                        if enabled). This protectes the archive from having\n			important files removed from it. It also severaly\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure\n			[OPTIONAL]\n\n  DEEPER                An extension of the DEEP mode. Every single file\n                        present within the archive will be tested in the same\n                        manner as DEEP mode. This can be extremely slow for\n                        large archives, especially those containing many\n                        smaller files. However it was included for maximum\n                        safety, and those running background checkers who are\n                        not concerned with speed. If used this function\n                        overrides DEEP mode.\n                        [OPTIONAL]\n\n  DUMP=<filename>       A feature where any files deleted from an archive are\n                        appended to an lha file of the given filename. This\n                        will slow down the checker somewhat but does ensure\n                        that any files that are removed that shouldn''t have\n                        been are not lost forever. You should keep tabs on\n                        this file because it will soon grow to be quite\n                        large. When using backlog stripping, files removed\n                        due to them being present in the backlog list will\n                        not be copied to the dump file. This will help to\n                        reduce replication of the same files being present\n                        in the dump file over and over again.\n                        [OPTIONAL]\n\n  LOGFILE=<filename>    Causes details of all files removed to be written to\n                        a logfile of the given name. Quite useful to allow any\n                        files stripped by accident, to be taken from the dump\n                        and replaced within the correct archive.\n                        [OPTIONAL]\n\n@ENDNODE\n\n@NODE addconfig "Adding Configuration"\n\n                  [ A D D I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the adding facilities of the program. These can be set up\nto add a maximum of 99 files to every archive. These tooltypes except the\nFASTADD are followed by a number from 1 to 99, for each file you should\nspecify these tooltypes once. ie SRCNAME.1, DESTNAME.1, RANDOMCHARS.1 etc.\nthen for the next file SRCNAME.2, DESTNAME.2 etc..\n\nFinally there is the FASTADD which is a totally seperate (very fast) method\nof adding files which is explained below.\n\n\n\n  SRCNAME.x=<filename>  This is the tooltype which enables the adding part\n                        of the checker. You can add upto 99 different files\n                        by specifying ''SRCNAME.1'' through to ''SRCNAME.99''.\n                        Each of the following tooltypes should run in a\n                        similar manner, starting at 1, upto 99. This tooltype\n                        specifies the full path the file file to be added to\n                        the archive.\n                        [OPTIONAL]\n\n  DESTNAME.x=<string>   This tooltype defines the name that the file is added\n                        to the archive is called. It may be a path containing\n                        subdirectories (so HERE/IS/MY/ADD.TXT is fine). This\n                        is required for each file to be added to the archive.\n                        The name can also contain ? symbols, each of which\n                        will be replaced with a random character (chosen from\n                        the list in the tooltype below or from the default\n                        list).\n                        [REQUIRED FOR EACH SRCNAME TOOLTYPE]\n\n  RANDOMCHARS.x=<string>This is the list of random characters used to replace\n                        any ? symbols in the destination filename for adds.\n                        If this tooltype is not present the list defaults to\n                        A-Z and 0-9.\n                        [OPTIONAL]\n\n  ANAGRAM.x             This tooltype will specify that each letter from the\n                        random character string can only be used once. This\n                        means you can create anagrams of strings. If you\n                        specify ????? as the destination name, and HELLO as\n                        the random character string, then using this option\n                        you will get random anagrams of the word HELLO with\n                        each character used once only.\n                        [OPTIONAL]\n\n  DESTLIST.x=<filename> This can be used as an alternative to specifying\n                        the destination filename in DESTNAME.x above. This\n                        allows you to have a file containing a list of\n                        possible destination names and one will be chosen\n                        at random. DESTNAME.x will always take priority over\n                        this option and if you specify both, the string in\n                        DESTNAME.x will be used. Notice that the filenames in\n                        this list are processed in the same manner as those\n                        from DESTNAME.x meaning you can still use ? as a\n                        random character, and directory names are allowed.\n                        [OPTIONAL]\n\n  COMMENT.x=<string>    Set the filenote (filecomment) of the add to whatever\n                        is contained within this tooltype\n                        [OPTIONAL]\n\n  DELPROTECT.x          Protects the file add against deletion. This only\n                        prevents the file being deleted once it has been\n                        extracted from the archive, it doesnt stop you from\n                        deleting it from the archive.\n                        [OPTIONAL]\n\n\n  NOSTAMP.x             A tooltype which prevents timestamping. If this\n                        tooltype is omitted, certain codes (listed below)\n                        will be replaced with the current time and date.\n                        If you are using non text files as adds (ie pictures\n                        or executables etc) then you will want to make sure\n                        that any occurances of these codes present in the\n                        non text files adds are not replaced with the time\n                        and date.\n                        [OPTIONAL]\n\n  FASTADD=<filename>    An LHA/LZH file containing adds (or anything else)\n			Which will be appended to the file being checked.\n			This method of adding is very fast, due to the fact\n			that the files are already compressed within the\n			archive so there is no need to compress them into the\n			archive being tested. The one disadvantage of this\n			method is it is not possible to have random filenames\n                        or to have the control codes for timestamping. You\n			should be careful to make sure that the file you are\n			is actually an LHA/LZH archive, because this program\n			will simply proceed to tag it onto the lha/lzh\n			archive being tested, and you could easily end up with\n			a corrupted archive.\n			[OPTIONAL]\n\n\nTimestamp facilities are also available. The following codes present in any\nadded file (except FASTADD archives) will be replaced with the current date\nand time in the given format:\n\n\n        DD/MM/YY  - replaced by the date in UK format (ie 25/12/95)\n\n        DD-MMM-YY - replaced by the date in system format (ie 25-Dec-95)\n\n        HH:MM:SS  - replaced by the time including seconds (ie 23:18:56)\n\n        HH:MM     - replaced by the time without seconds (ie 23:18)\n\n\nIMPORTANT\n\n 1 - Read the note on disabling timestamping above if you are using\n     non text adds (ie GIF/IFF/EXE).\n\n 2 - The above codes are case sensitive, dd/mm/yy will not do - they must\n     be EXACTLY as shown above.\n\n@ENDNODE\n\n@NODE miscconfig "Miscelleanous Configuration"\n\n           [ M I S C E L L E A N O U S   C O N F I G U R A T I O N ]\n\n\nThese tooltypes alter various other functions of the program related\nto the output etc.\n\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype supresses this output\n			and only the header will be displayed.\n			[OPTIONAL]\n\n  SHOWKILLED            This tooltype only takes effect when used with the\n                        QUIET option above. This causes the stripper to\n                        still list the files removed from the archive but\n                        not to list the whole contents.\n                        [OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specificly.\n			[OPTIONAL]\n\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are seperated by one or more spaces.Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysys routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\n@{B}Versions 0.xx@{UB}\n\nBeta test versions distributed to people on request\n\n\n@{B}Version 1.00@{UB}\n\nFirst public release version\n\n11/09/95\n\n\n@{B}Version 1.01@{UB}\n\nCRC Stripper, Bulletin and second output styles added.\n\n22/09/95\n\n\n@{B}Version 1.02@{UB}\n\nBug in the MAXLINES tooltype fixed, this caused random crashes on some\nmachines and also adds were never stripped with this option enabled.\n\nFASTADD option added.\n\nThe program now returns a error value of -1 if an\nerror occurred. This will be of use to NASTYDUPECHECK users.\n\nBug in the bulletin output fixed. If the filename of an add was long enough\nthe output of the bulletin would be skewed (it may be necessary to delete\nyour lhastripper.topdata file if this bug has affected you).\n\n10/10/95\n\n\n@{B}Version 1.03ß@{UB}\n\nBeta versions distributed to various people.\n\nSeveral small (non-fatal) bugs have been fixed. The top 10 list on the\nbulletin was sometimes getting disordered. Adding was listed as being OFF\non the output when only FASTADD mode was enabled.\n\n??/12/95\n\n\n@{B}Version 2.00@{UB}\n\nMajor overhaul in the add routines. They now work completely differently\nand are far more flexible than before.\n\nTimestamp facilities have been implemented.\n\n30/12/95\n\n\n@{B}Version 2.01@{UB} (Distributed to registered users on request only)\n\nNo testing is now done before stripping a file from the backlog list.\nThe individuality of the file crc coupled with its size means that no\nchecking is required, and the chances of it deleting a file by mistake are\nacceptable.\n\nA file present in the backlog list will now not be added to the dump file.\nThis saves repetition in the dump file.\n\nFiles are added to the backlog list even if they are already present, this\nstops them from getting ''PHASED OUT'' of the list.\n\nThe bulletin output routines no longer returns a value of -1\n(Thanks to SiRE for pointing out this problem)\n\n31/12/95\n\n\n@{B}Version 2.02@{UB}\n\nThe dump file was not closed properly under certain\ncircumstances. This caused the dump file to be corrupted.\n(Thanks to MDR for helping me find this one)\n\nTwo bugs in the new adding routines were causing the stripper to crash\non some machines.\n(Thanks to eNZO and SiRE for helping me sort this one)\n\nThe Top Ten wasnt updating (since v2.00) in the bulletin\n(Again thanks to MDR)\n\nTooltypes COMMENT.x and DELPROTECT.x added\n\nFixed a bug (another) in the new adding routines, causing it to lock\nrandomly when DESTLIST was used. (Thanks to eNZO and SARGE for helping\nme track this one down).\n\n17/01/96\n\n@{B}Version 2.03@{UB}\n\nMade some slight modifications to the intelligent analysis routine which\nwill help to cut down problems with the stripper removing files which\nare not adds.\n\nPlugged a 10k memory leak if fast adding was enabled.\n\nNow includes optional hit and miss stripping. Using the HITLIST HITCOUNT\nMISSLIST MISSCOUNT tooltypes.\n\nFound a bug whereby CRC stripping would not take place if the STRIPLIST\nfunction was disabled.\n\nAdded LOGFILE function whereby details of files removed are written into a\nlog file.\n\n09/07/96\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned know who they are\n\n  Also a quick hello must go to the following dudes:\n\n    Chelsea, Dark Angel, Epsilon, Icon, Zoltrix, rUFF Stones, MDR\n    Zorro, JR., Demons, Cruise, iggy, cat, zandor/sr, sasha, ace,\n    deature, prolix, pingu, |>|s<()r|>|/\, Abrasax, the undertaker.\n\n  Special thanks to Cruise, Enzo and MDR for their help and suggestions for\n  improvements... and anyone else who helped me with bug reports.... the\n  list of peeps who have helped is getting quite large now, so ill just say\n  THANKS without listing any names...\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support..... unlikely unless i get detailed information\n			 on the LZX file format.\n\n	GUI Interface... Gui program to maintain the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests).\n\n  I can be contacted on many of the uks boards, also a few euro boards\n  (but dont expect a fast reply from these - its expensive calling europe)\n\n  You can also e-mail me at [email removed] or you could try\n  catching me on the Amiga Elite Channel on IRC. (shouldnt be too hard hehe)\n\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Diz Design	- Chill/976 Ev!L/Data Division\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',23914,1,0,NULL,NULL,'xpstr203','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr204','XPSTR204.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR204.LZX',NULL,'XIM','LHAStripper',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',46904,0,0,NULL,NULL,'xpstr204','scan',1780048843);
INSERT INTO door_catalog VALUES('xpstr205','XPSTR205.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XPSTR205.LHA','LHAStripper','XIM','LHAStripper',NULL,NULL,NULL,'\_ | _/. _ Y .   /___). ___). ___) .-----. / .  //  __|/ |_/ _)_|___ .\___ .\ |v2.05| \__|_\ .|::|__|:|____)_____/_____/ `-----''',replace('___._______ _____________________\n\_ | _/. _ Y .   /___). ___). ___) .-----.\n/ .  //  __|/ |_/ _)_|___ .\___ .\ |v2.05|\n\__|_\ .|::|__|:|____)_____/_____/ `-----''\n+-----\_|--------------------------------+\n: __/\__ .-----------------------. __/\__:\n| \ Oo / |  The kewlest LHA/LZH  | \ oO /|\n: /_ ._\ |    stripper around    | /_. _\:\n: ¯¯\/¯¯ | ANOTHER LITTLE UPDATE | ¯¯\/¯¯:\n:        `-----------------------''       :\n`-[REbEL/QTX]-----------------[16.07.96]-''\n','\n',char(10)),'LHAStripper.guide',replace('@DATABASE "/XPRESS StRiP.GUIDE"\n@WIDTH 80\n\n@NODE main "/XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder"\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n              /XPRESS StRiP - Intelligent LHA/LZH Stripper/Adder\n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[     b U L L E T I N   O U T P U T     ]" LINK bull}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[        r E G I S T R A T I O N        ]" LINK register}\n\n                  @{"[             c R E D I T S             ]" LINK credits\n\n\n\n                            vERSiON 2.05 (16/07/96)\n\n''Oh no here we go again.. with another load of reg''d versions to assemble ;)''\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n  This little door, is an advanced LHA/LZH Stripper Adder with intelligent\n  analyse routines which are used to determine and eliminate the adds from\n  an LHA/LZH archive.\n\n  So what makes this stripper any different from the many other strippers\n  available? Well if set up correctly this stripper will eliminate 99% of\n  all adds from archives. This is thanks to the intelligent strip routines,\n  there is no need for huge strip lists, in fact the program will run quite\n  happily with no strip list at all.\n\n  The stripper is also unusually fast for an intelligent stripper, normally\n  intelligent strippers extract each file from the archive and use routines\n  to determine whether or not the file is an add or not, this is not simply\n  the case with this stripper, it also uses routines to determine without\n  extracting, whether or not the file is an addy, therefore removing the\n  speed bottleneck of having to extract the file if not necessary.\n\n  This utility is also capable of adding adds with specified or random\n  filenames, therefore defeating many strippers available today. It is\n  possible to add as many or as few adds as you require and the characters\n  selected for the random filenames can be specified, thereby defeating all\n  but the most intelligent of strippers.\n\n  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nCopy all of the files from the BBS drawer in this archive to the same place\nin your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      FCheck/\n         LHA.info\n         LZH.info\n      Doors/\n         LHAStripper/\n            LHAStripper\n            LHAStripper.guide\n            LHAStripper.info\n            Lha.list.cfg\n            Lha.nostrip.cfg\n            Lha.strip.cfg\n            Lha.crc.cfg\n            Lha.hit.cfg\n            Lha.miss.cfg\n\n\nThis utility does require WB2 or higher, and you MUST have a copy of LHA in\nthe current path (C: is a good place) if you enable analysis or adding.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\n\nThis door is configured using the standard tooltypes method of /X 4.xx\nThe LHAStripper.info icon contains tooltypes to configure many aspects\nof this program.\n\n\n            @{"STRIPPING CONFIGURATION" LINK stripconfig}\n\n            @{"ADDING CONFIGURATION" LINK addconfig}\n\n            @{"MISCELLEANOUS CONFIGURATION" LINK miscconfig}\n\n@ENDNODE\n\n@NODE stripconfig "Stripping Configuration"\n\n               [ S T R I P P I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the stripping facilities of the program. If these are set\nup well, you can obtain very impressive results from this stripper.\n\n\n\n  STRIPLIST=<filename>	Specifies a file containing a list of filenames\n			which will be stripped if found in an archive.\n			filenames listed in here will override MAXSIZE and\n			MINSIZE values. This is the conventional @{"STRIPLIST" LINK STRIPMODE}\n			method which most strippers employ.\n			[OPTIONAL]\n\n  NOSTRIPLIST=<filename> A file containing a list of filenames which will\n			NOT be removed from an archive under any\n			circumstances.\n			[OPTIONAL]\n\n  HITLIST=<filename>    A file containing a list of key words which are used\n                        to determine whether the file being analysed is an\n                        advert or not. If any words that are listed in this\n                        @{"HITLIST" LINK HITMODE} are in the file being tested, they will be\n                        counted, and if there are more than HITCOUNT the file\n                        is considered to be an advert. If this function is\n                        not used. files will simply be tested to ensure they\n                        are one of the following, TEXT, IFF ILBM, IFF ANIM,\n                        GIF, JPEG.\n                        [OPTIONAL]\n\n  HITCOUNT=<number>     The number of matching words from the HITLIST that\n                        need to be found to trigger stripping. (Defaults to 1)\n                        [OPTIONAL]\n\n  MISSLIST=<filename>   A file containing a list of key words which are used\n                        to make sure a file is left intact. This is useful\n                        to prevent ARexx and AmigaGuide, Docs etc. from\n                        being recognised as adverts. It works in exactly the\n                        same way as HITLIST/HITCOUNT.\n                        [OPTIONAL]\n\n  MISSCOUNT=<number>    The number of matches of words from the MISSLIST to\n                        prevent the file being stripped. (Defaults to 1)\n                        [OPTIONAL]\n\n  CRCLIST=<filename>	A file containing a list of CRC''s and file lengths.\n			This will enable @{"CRC" LINK CRCMODE} stripping.\n			[OPTIONAL]\n\n  BACKLOG=<number>	This is another option which if specified enables\n			the @{"BACKLOG" LINK BACKLOGMODE} stripping.\n			[OPTIONAL]\n\n  STRIPCHARS=<string>   A list of illegal characters. This tooltype will\n			enable @{"ILLEGAL CHARACTER" LINK ICHARMODE} stripping.\n			[OPTIONAL]\n\n  MAXSIZE=<number>	Files over this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MINSIZE=<number>	Files under this size will never be stripped unless\n			listed in the STRIPLIST file.\n			[OPTIONAL]\n\n  MAXLINES=<number>	Files that are extracted from the archive for testing\n			must be less than maxlines. This means that in DEEP\n			mode, no text files will be stripped if they are more\n			than this long. In normal mode, only the adds selected\n			by the analysis routines for extraction are tested.\n			[OPTIONAL]\n\n  MINLINES=<number>	The minimum number of lines. See MAXLINES for full\n			description.\n			[OPTIONAL]\n\n  MAXARCSIZE=<number>	This is used with DEEPER mode. If the archive is above\n			the size listed here the stripper will drop out of\n			DEEPER mode. If you have specified any modes which\n			normally are overridden by DEEPER mode (for example\n			DEEP or ANALYSE) the stripper will then run in these\n			modes instead.\n			[OPTIONAL]\n\n  ANALYSE		Enables the intelligent @{"ANALYSIS" LINK ANALYSEMODE} routines. Leave this\n			out if you wish to use this as a more conventional\n			stripper, by only using STRIPLIST, NOSTRIPLIST etc.\n			[OPTIONAL]\n\n  DEEP			Enables deep analysis mode, this makes the stripper\n			much slower, once an assumed add is located, it will\n			be extracted and examined to ensure it is the correct\n			file type (and the hit and miss functions are executed\n                        if enabled). This protects the archive from having\n			important files removed from it. It also severely\n			slows down the process, and normally the stripper does\n			not need to be operated in this mode. It has however\n			been included as a safety measure.\n			[OPTIONAL]\n\n  DEEPER                An extension of the DEEP mode. Every single file\n                        present within the archive will be tested in the same\n                        manner as DEEP mode. This can be extremely slow for\n                        large archives, especially those containing many\n                        smaller files. However it was included for maximum\n                        safety, and those running background checkers who are\n                        not concerned with speed. If used this function\n                        overrides DEEP mode. @{B}WARNING: It is inadvisable to use\n			DEEPER mode unless you are using hit / miss stripping.\n			Failure to heed this warning could result in all text\n			files being removed from an archive.@{UB}\n                        [OPTIONAL]\n\n  DUMP=<filename>       A feature where any files deleted from an archive are\n                        appended to an lha file of the given filename. This\n                        will slow down the checker somewhat but does ensure\n                        that any files that are removed that shouldn''t have\n                        been are not lost forever. You should keep tabs on\n                        this file because it will soon grow to be quite\n                        large. When using backlog stripping, files removed\n                        due to them being present in the backlog list will\n                        not be copied to the dump file. This will help to\n                        reduce replication of the same files being present\n                        in the dump file over and over again.\n                        [OPTIONAL]\n\n  LOGFILE=<filename>    Causes details of all files removed to be written to\n                        a logfile of the given name. Quite useful to allow any\n                        files stripped by accident, to be taken from the dump\n                        and replaced within the correct archive.\n                        [OPTIONAL]\n\n@ENDNODE\n\n@NODE addconfig "Adding Configuration"\n\n                  [ A D D I N G   C O N F I G U R A T I O N ]\n\n\nThese configure the adding facilities of the program. These can be set up\nto add a maximum of 99 files to every archive. These tooltypes except the\nFASTADD are followed by a number from 1 to 99, for each file you should\nspecify these tooltypes once. ie SRCNAME.1, DESTNAME.1, RANDOMCHARS.1 etc.\nthen for the next file SRCNAME.2, DESTNAME.2 etc..\n\nFinally there is the FASTADD which is a totally separate (very fast) method\nof adding files which is explained below.\n\n\n\n  SRCNAME.x=<filename>  This is the tooltype which enables the adding part\n                        of the checker. You can add upto 99 different files\n                        by specifying ''SRCNAME.1'' through to ''SRCNAME.99''.\n                        Each of the following tooltypes should run in a\n                        similar manner, starting at 1, upto 99. This tooltype\n                        specifies the full path the file file to be added to\n                        the archive.\n                        [OPTIONAL]\n\n  DESTNAME.x=<string>   This tooltype defines the name that the file is added\n                        to the archive is called. It may be a path containing\n                        subdirectories (so HERE/IS/MY/ADD.TXT is fine). This\n                        is required for each file to be added to the archive.\n                        The name can also contain ? symbols, each of which\n                        will be replaced with a random character (chosen from\n                        the list in the tooltype below or from the default\n                        list).\n                        [REQUIRED FOR EACH SRCNAME TOOLTYPE]\n\n  RANDOMCHARS.x=<string>This is the list of random characters used to replace\n                        any ? symbols in the destination filename for adds.\n                        If this tooltype is not present the list defaults to\n                        A-Z and 0-9.\n                        [OPTIONAL]\n\n  ANAGRAM.x             This tooltype will specify that each letter from the\n                        random character string can only be used once. This\n                        means you can create anagrams of strings. If you\n                        specify ????? as the destination name, and HELLO as\n                        the random character string, then using this option\n                        you will get random anagrams of the word HELLO with\n                        each character used once only.\n                        [OPTIONAL]\n\n  DESTLIST.x=<filename> This can be used as an alternative to specifying\n                        the destination filename in DESTNAME.x above. This\n                        allows you to have a file containing a list of\n                        possible destination names and one will be chosen\n                        at random. DESTNAME.x will always take priority over\n                        this option and if you specify both, the string in\n                        DESTNAME.x will be used. Notice that the filenames in\n                        this list are processed in the same manner as those\n                        from DESTNAME.x meaning you can still use ? as a\n                        random character, and directory names are allowed.\n                        [OPTIONAL]\n\n  COMMENT.x=<string>    Set the filenote (filecomment) of the add to whatever\n                        is contained within this tooltype\n                        [OPTIONAL]\n\n  DELPROTECT.x          Protects the file add against deletion. This only\n                        prevents the file being deleted once it has been\n                        extracted from the archive, it doesn''t stop you from\n                        deleting it from the archive.\n                        [OPTIONAL]\n\n\n  NOSTAMP.x             A tooltype which prevents timestamping. If this\n                        tooltype is omitted, certain codes (listed below)\n                        will be replaced with the current time and date.\n                        If you are using non text files as adds (ie pictures\n                        or executables etc) then you will want to make sure\n                        that any occurrences of these codes present in the\n                        non text files adds are not replaced with the time\n                        and date.\n                        [OPTIONAL]\n\n  FASTADD=<filename>    An LHA/LZH file containing adds (or anything else)\n			Which will be appended to the file being checked.\n			This method of adding is very fast, due to the fact\n			that the files are already compressed within the\n			archive so there is no need to compress them into the\n			archive being tested. The one disadvantage of this\n			method is it is not possible to have random filenames\n                        or to have the control codes for timestamping. You\n			should be careful to make sure that the file you are\n			is actually an LHA/LZH archive, because this program\n			will simply proceed to tag it onto the lha/lzh\n			archive being tested, and you could easily end up with\n			a corrupted archive.\n			[OPTIONAL]\n\n\nTimestamp facilities are also available. The following codes present in any\nadded file (except FASTADD archives) will be replaced with the current date\nand time in the given format:\n\n\n        DD/MM/YY  - replaced by the date in UK format (ie 25/12/95)\n\n        DD-MMM-YY - replaced by the date in system format (ie 25-Dec-95)\n\n        HH:MM:SS  - replaced by the time including seconds (ie 23:18:56)\n\n        HH:MM     - replaced by the time without seconds (ie 23:18)\n\n\nIMPORTANT\n\n 1 - Read the note on disabling timestamping above if you are using\n     non text adds (ie GIF/IFF/EXE).\n\n 2 - The above codes are case sensitive, dd/mm/yy will not do - they must\n     be EXACTLY as shown above.\n\n@ENDNODE\n\n@NODE miscconfig "Miscelleanous Configuration"\n\n           [ M I S C E L L E A N O U S   C O N F I G U R A T I O N ]\n\n\nThese tooltypes alter various other functions of the program related\nto the output etc.\n\n\n  QUIET			During normal operation the stripper will list the\n			files present in the archive and indicate which ones\n			have been removed. This tooltype suppresses this\n			output and only the header will be displayed.\n			[OPTIONAL]\n\n  SHOWKILLED            This tooltype only takes effect when used with the\n                        QUIET option above. This causes the stripper to\n                        still list the files removed from the archive but\n                        not to list the whole contents.\n                        [OPTIONAL]\n\n  REPORT		This tooltype will cause the program to display a line\n			of text after the operation indicating the number of\n			files removed, the old archive length and the new\n			archive length and a percentage size.\n			[OPTIONAL]\n\n  SCREENCLEAR		This tooltype will force the program to clear the\n			screen before it writes its output.\n			[OPTIONAL]\n\n  OUTPUT=<number>	This will choose between the two different ANSI\n			outputs available. The first was drawn by OrdYne\n			and the second by DARK ANGEL/976 LEADER. If this\n			tooltype is not present, the output will be chosen\n			between the two at random. You should specify\n			OUTPUT=1 or OUTPUT=2 if you want to choose one\n			specifically.\n			[OPTIONAL]\n\n\n@ENDNODE\n\n@NODE STRIPMODE "Filename Match Stripping"\n\nThis is the method that most archive strippers use to remove adds. It simply\ncompares a list of known add filenames with the ones present in the archive,\nand removes any that match.\n\n@{U}Advantages:@{UU}\n\nThe contents of the add are not checked, therefore cannot mislead the stripper\nand it adds which have the uploader, time, date etc stamped into them do not\naffect the routine.\n\nIt is not necessary to extract the files from the archive so speed is very\ngood.\n\n@{U}Disadvantages:@{UU}\n\nAdds with randomly generated filenames cannot be removed with this method.\n\nFilenames have to be manually added to the filename list.\n\n@ENDNODE\n\n@NODE HITMODE "Hit / Miss Word Stripping"\n\nThis is becoming quite a popular method of stripping, with most other\nstrippers which employ this technique, each file is extracted from the\narchive and tested for the HIT and MISS words.\n\nIf any of the MISS words are present then this file must not be removed\n(it is useful to specify things like ARexx commands, Amigaguide commands\nin here to ensure ARexx scripts and AmigaGuide files are not removed).\n\nIf any of the HIT words are present then this file will be removed from the\narchive. It is usual to specify things like NODE, SYSOP, HQ, RINGDOWN etc\nin this list. In many strippers (this one included) it is also possible to\nspecify the number of HITS or MISSES required to trigger the strip/do not\nstrip functions.\n\nSince it is necessary to extract the files from the archive to determine if\nthey have HIT / MISS words in them this function works best in DEEP or DEEPER\nmodes, since in normal operating mode only a very limited amount of files\nare extracted from the archive in an attempt to keep the running speed up.\n\nEven so, this function is still very useful in normal operating mode to\nensure normal txt files are not confused with adds in those files which are\nextracted and tested. Use of this function in normal operating mode should\nfurther reduce the number of erroneous strips.\n\n@ENDNODE\n\n@NODE CRCMODE "CRC Match Stripping"\n\nIn an LHA/LZH archive, each file present has a CRC (checksum) stored for it,\nthis stripping method will remove any files present in the archive with a\nchecksum and filesize that matches any of those listed in the file named\nin this tooltype.\n\nThe format for entering checksums and file sizes into the file is as follows:\n\n1 line per entry, first on the line is the checksum value, which is always\nfour hex digits long, followed by the filesize which is of variable length.\nThese two are separated by one or more spaces. Then (optionally) a comment\nis allowed by immediately following the file size with a ; (semi colon).\n\n@{U}Examples@{UU}\n\nAC12 3657;This is the add for xxx bbs\nB12A 75757;This is another\n\nto find out the stored CRC for an add within an archive simply use the VV\ncommand of lha to get a full listing of all the details stored on each file.\n(eg. LHA VV archive.lha)\n\n@{U}Advantages@{UU}\n\nRandomly named adds can easily be removed.\n\nSpeed is high as with filename matching because the files need not be\nextracted from the archive.\n\n@{U}Disadvantages@{UU}\n\nThe add must be EXACTLY the same every time otherwise the CRC will differ.\nThis means no time/date/uploader stamping can take place on the add.\n\nFile CRC and sizes have to be manually added to the CRC list file.\n\n@ENDNODE\n\n@NODE BACKLOGMODE "Backlog Stripping"\n\nBacklog mode will keep a log of the last files stripped out of an archive,\nand if they show up again while they are present in the log, they will\nautomatically be removed without any analysis whatsoever. This tooltype\nspecifies the number of backlog entries that are kept. The search of the\nbacklog is extremely fast, and i have mine set to 256 entries with no\nnoticeable speed loss.\n\n@{U}Advantages@{UU}\n\nCommon Files will be automatically removed with no analysis. This is extremely\neffective in deep mode, where the analysis time is far less.\n\nAll this is done automatically, removing the need to add files to a list.\n\n@{U}Disadvantages@{UU}\n\nThere is a very (very very) small possibility that a file (which is not an\nadd) could match the details stored in the backlog file. If by some remote\nchance, its filesize and checksum were exactly the same.\n\nIf i file has been removed accidentally by the stripper, and it crops up\nin another archive it will also be removed from there.\n\n@ENDNODE\n\n@NODE ICHARMODE "Illegal Character Stripping"\n\nThis tooltype lists any characters which should cause the file to be removed\nfrom the archive if any of these characters are present in the filename.\n\n@{U}Advantages@{UU}\n\nThe search for these characters is extremely fast.\n\n@{U}Disadvantages@{UU}\n\nUnless the characters are chosen very carefully, it is possible to end up\nremoving vital files from the archive, which the creator has named with\ncharacters present in your list.\n\n@ENDNODE\n\n@NODE ANALYSEMODE "Analysis Routines"\n\nThese form the main backbone of the checker. Without these it functions purely\nin the capacity of many of the other strippers available. It searches the \nfilename and CRC lists for matching files. Disabling these complex and\nintelligent analysis routines defeats the object of this stripper. They should\nbe left enabled at all times, unless you have problems with them for some\nreason.\n\n@ENDNODE\n\n@NODE bull "Bulletin Output"\n\nDuring normal operation the LHAStripper main program will be run from the\nfcheck drawer by LHA.info and LZH.info. The stripper is capable of creating\na bulletin screen, with many stats about its current operational status. I\nfirst saw this working in SISSY, the lha/lzx stripper/adder/checker written\nby crew^one/myth so i should probably say a thanks to him for that idea.\n\nTo create the bulletin you can run the LHAStripper main program from a CLI\nor a script with the following parameters:\n\n  LHAStripper <bulletin filename> MAKEBULL\n\nthe MAKEBULL switch tells the stripper you wish to make the bulletin given\nin the filename rather than check it as an LHA/LZH file.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\n@{B}Versions 0.xx@{UB}\n\nBeta test versions distributed to people on request\n\n\n@{B}Version 1.00@{UB}\n\nFirst public release version\n\n11/09/95\n\n\n@{B}Version 1.01@{UB}\n\nCRC Stripper, Bulletin and second output styles added.\n\n22/09/95\n\n\n@{B}Version 1.02@{UB}\n\nBug in the MAXLINES tooltype fixed, this caused random crashes on some\nmachines and also adds were never stripped with this option enabled.\n\nFASTADD option added.\n\nThe program now returns a error value of -1 if an\nerror occurred. This will be of use to NASTYDUPECHECK users.\n\nBug in the bulletin output fixed. If the filename of an add was long enough\nthe output of the bulletin would be skewed (it may be necessary to delete\nyour lhastripper.topdata file if this bug has affected you).\n\n10/10/95\n\n\n@{B}Version 1.03ß@{UB}\n\nBeta versions distributed to various people.\n\nSeveral small (non-fatal) bugs have been fixed. The top 10 list on the\nbulletin was sometimes getting disordered. Adding was listed as being OFF\non the output when only FASTADD mode was enabled.\n\n??/12/95\n\n\n@{B}Version 2.00@{UB}\n\nMajor overhaul in the add routines. They now work completely differently\nand are far more flexible than before.\n\nTimestamp facilities have been implemented.\n\n30/12/95\n\n\n@{B}Version 2.01@{UB} (Distributed to registered users on request only)\n\nNo testing is now done before stripping a file from the backlog list.\nThe individuality of the file crc coupled with its size means that no\nchecking is required, and the chances of it deleting a file by mistake are\nacceptable.\n\nA file present in the backlog list will now not be added to the dump file.\nThis saves repetition in the dump file.\n\nFiles are added to the backlog list even if they are already present, this\nstops them from getting ''PHASED OUT'' of the list.\n\nThe bulletin output routines no longer returns a value of -1\n(Thanks to SiRE for pointing out this problem)\n\n31/12/95\n\n\n@{B}Version 2.02@{UB}\n\nThe dump file was not closed properly under certain\ncircumstances. This caused the dump file to be corrupted.\n(Thanks to MDR for helping me find this one)\n\nTwo bugs in the new adding routines were causing the stripper to crash\non some machines.\n(Thanks to eNZO and SiRE for helping me sort this one)\n\nThe Top Ten wasn''t updating (since v2.00) in the bulletin\n(Again thanks to MDR)\n\nTooltypes COMMENT.x and DELPROTECT.x added\n\nFixed a bug (another) in the new adding routines, causing it to lock\nrandomly when DESTLIST was used. (Thanks to eNZO and SARGE for helping\nme track this one down).\n\n17/01/96\n\n@{B}Version 2.03@{UB}\n\nMade some slight modifications to the intelligent analysis routine which\nwill help to cut down problems with the stripper removing files which\nare not adds.\n\nPlugged a 10k memory leak if fast adding was enabled.\n\nNow includes optional hit and miss stripping. Using the HITLIST HITCOUNT\nMISSLIST MISSCOUNT tooltypes.\n\nFound a bug whereby CRC stripping would not take place if the STRIPLIST\nfunction was disabled.\n\nAdded LOGFILE function whereby details of files removed are written into a\nlog file.\n\n09/07/96\n\n@{B}Version 2.04@{UB}\n\nFixed a bug with the date/timestamping which had cropped in at the last\nversion. Thanks to MDR and PICARD for noticing this one.\n\nWhen running in DEEP or DEEPER modes, IFF/GIF/IFF-ILBM/IFF-ANIM will only\nbe stripped after finding 2 consecutive TXT adds. This is to protect the\nformats from being removed from the main archive contents.\n\nAn extra section on HIT / MISS word stripping was added to this guide,\nsince this seemed to be causing confusion for many people, due to the way\nin which this stripper works it does not function quite the same way as in\nmany other strippers which employ HIT / MISS word stripping.\n\n@{B}Version 2.05@{UB}\n\nSlight alteration to the text analysis routine. Should help to tighten up\nfalse stripping (again).\n\nFiles listed in the striplist sometimes were not stripped (thanks to numerous\npeople who mentioned this bug, especially MDR). The problem affects files with\nan underscore symbol (_) in the filename. From analysis it seems that the\nproblem lies within the dos function calls ParsePatternNoCase and\nMatchPatternNoCase. I am certainly not claiming that it is definately a bug in\nDOS and not my code, but that is the way it seems. I have managed to code a\nworkaround, and all should work fine now.\n\nAdded MAXARCSIZE tooltype. Used with DEEPER mode. For those who are using\nthis you can now specify the maximum archive size to be used. If the archive\nis above this size it will drop out of DEEPER mode.\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  First off many thanks must go to the beta testers of this release, who have\n  continued to use this program thru its various quirks and bugs, which you\n  helped to bring to my attention. They people concerned know who they are\n\n  Also a quick hello must go to the following dudes:\n\n    Chelsea, Dark Angel, Epsilon, Icon, Zoltrix, rUFF Stones, MDR\n    Zorro, JR., Demons, Cruise, iggy, cat, zandor/sr, sasha, ace,\n    deature, prolix, pingu, |>|s<()r|>|/\, Abrasax, the undertaker.\n\n  Further greets go to all those who spend all their time (like myself)\n  hanging out on the Amiga Elite channel on IRC.\n\n  Special thanks to Cruise, Enzo and MDR for their help and suggestions for\n  improvements... and anyone else who helped me with bug reports.... the\n  list of peeps who have helped is getting quite large now, so ill just say\n  THANKS without listing any names...\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\n  This little tool, was originally designed for my own use only, but due to\n  ever increasing requests from sysops, i decided to release it publicly.\n  Therefore it is unlikely there will be many updates for this little tool.\n  There have been one or two features requested many times by sysops i have\n  spoken to. Some of these may or may not be implemented at a future date,\n  but they are listed below all the same.\n\n\n	LZX Support..... unlikely unless i get detailed information\n			 on the LZX file format.\n\n	GUI Interface... Gui program to maintain the filename and\n			 file CRC lists.\n\n	Any other updates will be considered and probably ignored, but\n	if I like the idea, you never know.\n\n@ENDNODE\n\n@NODE register "Registration"\n\n                         [ r E G I S T R A T I O N ]\n\n\n  This little program is in no way crippled and requires no form of payment\n  to use. It is FREEWARE. Although registered versions which will display\n  your name in the header text are available on request (provided there are\n  not too many requests).\n\n  I can be contacted on many of the UKs boards, also a few Euro boards\n  (but don''t expect a fast reply from these - its expensive calling Europe)\n\n  You can also e-mail me at [email removed] or you could try\n  catching me on the Amiga Elite Channel on IRC. (shouldn''t be too hard hehe)\n\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ c R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - OrdYne (thx dude!)\n		- Dark Angel/976 LEADER (thx to u to!)\n\n  Diz Design	- Chill/976 Ev!L/Data Division\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',49715,1,0,NULL,NULL,'xpstr205','scan',1780048843);
INSERT INTO door_catalog VALUES('xta_st1m','XTA-ST1M.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XTA-ST1M.LHA',NULL,'XIM','-÷- Ecstatica BBS Presents -÷- A ''95 Product',NULL,'Instant','XTA','Called -÷< Ecsta-Stat v1.04 - A New Status Door For /X Boards         >÷-',replace('-÷- Ecstatica BBS Presents -÷- A ''95 Product\n                    Called\n-÷< Ecsta-Stat v1.04 - A New Status Door For\n                       /X Boards         >÷-\nReleased: 07-25-95, by Instant\n','\n',char(10)),'Ecsta-Stat.GuiDe',replace('@database Ecsta-Stat.GuiDe\n@$VER: Ecsta-Stat v1.04m By Instant/Independant - Guide File\n@node MAIN "Ecsta-Stat v1.04m (c) 07/95 Instant/Independant"\n\n\n\n\n\n\n                                Ecsta-Stat\n\n                              Version: 1.04m\n                                    By\n                            Instant/Independant\n\n\n    DISCLAIMER: The Author Takes no responsibility for any damage this\n      may cause you, your family, your pets, your friends, your house\n    your neighbourhood, your machine, any inventory in your house, your\n          country, your state or anything else you may think of.\n\n  tO EnCourage further development of any ECSTA-TOOLS programme ($1), and\nthe development of ''UNPROFOR (Working Title) - The Strategy Game for Amiga'' ($5)\n     Please send the money to me, see CONTACTS for further information\n\n\n@endnode\n@node CONTENTS "Ecsta-Stat v1.04 (c) 07/95 Instant/Independant"\n                 Welcome to my First Ami Express Release!\n      This is a fast and featurefull STATUS programme, which replaces\n     the internal ''S'' command, and any other ''S'' command you may have!\n\n   Anyway: Press any of THEESE buttons to go to the corresponding page!\n\n                          @{" Installation " link "Install"}\n                          @{" Contact " link "Contact"}\n                          @{" History " link "history"}\n                          @{" Other " link "OTHER"}\n\n\n\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node INSTALL "Installation Info for Ecsta-Stat v1.04 by Instant"\n                     How do you install this utility?\n                     ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                       UNARCHIVE ME-U.lha FROM BBS:\n         and everything will be placed where it should be placed!\n\n\n                  The Files that will be unarchived are:\n\n\n		Ecsta-Stat.rexx - Main Programme\n		Ecsta-Stat.Gui  - GUI\n		Cookies		- CookieFile\n		Random		- Randomize Programme\n\n             Theese files will be placed in a directory called\n                      ''DOORS:ECSTA-TOOLS/ECSTA-STAT/''\n\n\n           Also You Can Place ME in bbs:docs or the Above path.\n\n            To Add A Cookie or ten, just edit the COOKIE file!\n\n\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node HISTORY "In 1963 JKF Was Shot, in 1988 The Berlin Wall Crumbled, in 1991 Saddam Got his Ass Kicked!, In 1995 Instant Released Ecsta Stat"\nHISTORY\n-------\nVersion 0.99 - Added Everything (NEVER RELEASED)\nVersion 1.00 - Added Ansi BackGround (UNRELEASED)\nVersion 1.01 - Added Cookie File (UNRELEASED)\nVersion 1.02 - Added Guide File (UNRELEASED)\nVersion 1.03 - Made Installation Script (UNRELEASED)\nVersion 1.04 - LHAed The Whole Thing and Sent it away for a beta release (Release #0.99)\nVersion 1.04m- Added ANSI and ASCII logo,Made Cookie Work (Release #1)\n\n@Endnode\n@node CONTACT "First you turn left at 1st, then proceed allong west avenue for 30 blocks, when you come to a roadsight turn left and then right"\nCONTACT\n-------\nTo Contact The Author For Registration, Flames,  or Fan-Mail :)\ndo any of the following\n---\n\nVia Internet\n	Email : [email removed]\n        WWW   : http://powertech.no/~terjeba/ - Leave a Message in the GUestbook\n	IRC   : #amiga, #amiga!, #warez, #compuwar\n\nVia Modem\n  	     Ecstatica : +474U2FINDOUT - The Home of Ecsta-Tools\n	Bumble Bee Land: +474U2FINDOUT - Name: Instant (NUP,SYSPW)\n	 Basic Instinct: +474U2FINDOUT - Name: Instant\n	        OutPost: +46CANTBEBOTHERED2TYPETHEMIN - Name: Instant\n\nVia snailMail\n		Terje Alexander Barth\n		Fredtunveien 18\n		1370 Asker\n		Norway\n\n- Please send $1 if you REALLY Like this programme and want me to further develop it :)\n- Please send $5 or more if you would like the Game ''UN - Conflict Jugoslavia''\n  to be furhter developed!\n@ENDNODE\n@node OTHER\n\n             Other Usefull utilities to be released by me are\n             ------------------------------------------------\n\nEcsta-Req    	- Requester for ASCII, AREXX and "STUFF"\nEcsta-Chat	- Chat Door\nEcsta-DS	- Local/Sysop Download Door\nEcsta-Who	- Who Door\nEcsta-Front	- FrontDoor\nEcsta-Desert	- Strategy Game for /X\n@ENDNODE\n','\n',char(10)),NULL,NULL,15452,5,0,NULL,NULL,NULL,'scan',1780048843);
INSERT INTO door_catalog VALUES('xta_st21','XTA-ST21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XTA-ST21.LHA','Random','XIM','Random','2.0','Instant/Independant','XTA','Full Release Version by Instant/Independant Release date: 08-05-95, 09:10:40 THE BEST STATUS DOOR FOR /X EVER MADE!!!!!!!',replace('        =-= Ecsta-Stat v2.0 =-=\nFull Release Version by Instant/Independant\nRelease date: 08-05-95, 09:10:40\nTHE BEST STATUS DOOR FOR /X EVER MADE!!!!!!!\n','\n',char(10)),'Ecsta-Stat.GuiDe',replace('@database Ecsta-Stat.GuiDe\n@$VER: Ecsta-Stat v2.11 By Instant/Independant - Guide File\n@node MAIN "Ecsta-Stat v2.11 (c) 08/95 Instant/Independant"\n\n\n\n\n\n\n                              Ecsta-Stat v2.11\n                             Ecsta-Statin v1.0\n\n                                    By\n                            Instant/Independant\n\n\n    DISCLAIMER: The Author Takes no responsibility for any damage this\n      may cause you, your family, your pets, your friends, your house\n    your neighbourhood, your machine, any inventory in your house, your\n          country, your state or anything else you may think of.\n\n\ntO EnCourage further development and registration of any ECSTA-TOOLS programme\n      Please send me some cash  see CONTACTS for further information\n\n\n@endnode\n@node CONTENTS "Ecsta-Stat v2.11 (c) 08/95 Instant/Independant"\n\n                        Welcome to Ecsta-Stat v2.11\n                          The NEW S Ruler for /X\n\n   Anyway: Press any of THEESE buttons to go to the corresponding page!\n\n                          @{" Installation " link "Install"}\n                          @{" Configure" link "config"}\n                          @{" Design" link "DESIGN"}\n                          @{" Contact " link "Contact"}\n                          @{" History " link "history"}\n                          @{" Other " link "OTHER"}\n\n\n\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node configure "How To Configure Ecsta-Stat"\n\nEdit the File Ecsta-Stat.cfg, here is a description of what\nthe diffrent things mean\n\nLine 1: example	- The Name of the Design File, found in Designs/\nLine 2: ESC[44;37m - Ansi Colour Coding on how the OUTPUT should look like\nLine 3: 1 or 2    - 1= ONE LINE COOKIE, 2= TWO LINED COOKIE (32Chars each)\n\nLine 4: THIS IS THE BACKGROUND;FOREGROUND COLOURS USED FOR AXXESS O METER WHEN CORRECT AXX\nLine 5: THIS IS THE BACKGROUND;FOREGROUND COLOURS USED FOR AXXESS O METER WITH ALL OTHER AXXS\n\n\nExample for line 2:   [44;37m Instant  [0m<- Username with blue backgrund and\n                      ^^^^^^^^                 white foreground\n                         What You Need to Write, and how it will look\n\n\n\nNo Need to Change LINE 4 or 5!!!\n\n\n\n----\nCONFIGURING AXXLEVELS.CFG\n-------------------------\n\nEdit the file after the following Standards\n\n   line 1: NUMBER OF AXX LEVELS AVAILABLE (MAX 6 IN THIS VERSION )\nline 2-x : "AXXLEVEL NAME (MAX 8 LETTERS)" "AXX LEVEL IN NUMBERS"\n\nExample: Line 2: SYSOP 255\n                 ^^^^  ^^^\n                 |      `-= Axx Level #\n                 `-----= Axx Level Name\n\n\n@endnode\n@node design "How to Design your own Ecsta-Stat!"\n\n                       How to Design your OWN GUI!!!\n                       -----------------------------\n\nThis must be the FIRST status door with a 100% User Configurable Layout!\n\nYou can design your own layout with almost any editor, but i would personally\nreccomend a ANSI editor.\n\n------\nYOU NEED 2 FILES:\n\nDesign/designname.gui\ndesign/designname.s\n\nThe GUI file is just what it says, GUI\nThe S file is the DESIGN FILE!\n\nSEE THE EXAMPLE FOR MORE INFORMATION ON HOW TO MAKE IT!\n-------\n\n-------------------------------------------------------\nFORMAT OF KEYWORD:\n\n%<code><lines from top>;<characters from left>\n\n-KeyWord-	- What it is\n-----------------------------------------------------------------------------\n  U#1;3	- UseRNumber\n\n  UN1;1	- UseRname\n\n  ND1;1	- Node User is Connected to!\n\n  UP1;2	- User Location/Group\n\n  UT1;1	- User Phone Number\n\n  UA1;2	- User Axx Level\n\n  MW1;1	- Messages Written\n\n  UF1;1	- Uploaded Files\n\n  DF1;1	- Downloaded files\n\n  UB1;1	- Uploaded Bytes\n\n  DB1;1	- Downloaded Bytes\n\n  UC1;1	- User Calls\n\n  LC1;1	- Last Call in SECONDS or Sumthing, from Beginning of year :) USE LL instead for date\n\n  TU1;1	- TIme Used today (minuttes)\n\n  TM1;1 - Current Time\n\n  TL1;1	- Time left today..\n\n  TA1;1	- Time Available/limit\n\n  DT1;1	- Downloaded Bytes today\n\n  SL1;1 - Special Login Date, REMOVES YEAR... But Otherwise Identical to LL\n\n  DL1;1	- Download Limit per day\n\n  LI1;1	- Lines Per Page User Has\n\n  AA1;1	- Area Axx Level (Take The length of Name from access/xxxx.info)\n\n  RF1;1 - File Ratio\n\n  RB1;1 - Byte Ratio\n\n  RT1:1 - Ratio (1:6 for Example)\n\n  RS1;1 - Special Ratio Format (Example: <BYTE ONLY> / <FILE ONLY> / <BYTE AND FILE>)\n\n  ND1;1 - Node Nr User connected to\n\n  CN1;1 - Conference Name\n\n  UX1;1 - User Expert Mode\n\n  LL1;1 - Date of Last Login\n\n  BN1;1	- Board Name\n\n  BS1;1	- Board Sysop\n\n  BC1;1	- Calls to bbs\n\n  BN1;1	- Number of Nodes\n\n  CF1;1	- Chat Flag\n\n  VR1;1	- Amix Version\n\n  CK1;1	- Cookie !!!!!! MUST BE 70!!!!!!!!! (EDIT ECSTA-STAT.CFG line:3 = 1)\n\n  C11;1 - Line 1 of SHORT Cookie! (32 Characters per line) (EDIT ECSTA-STAT.CFG line:3 = 2)\n  C21;1 - Line 2 of Short Cookie! (32 Characters per line) (EDIT ECSTA-STAT.CFG line:3 = 2)\n\n  BO1;1 - Baud rate User Connected at\n\n  AN1;1 - Active Nodes (xx - 2 nodes, xxx- 3 nodes, xxxx-4 nodes, and soo on)\n\n  AM1;1 - Access''o''Meter (NEED LOTS OF SPACE :) Check Example:MINI)\n\n-----------------------------------------------------------------------------\n\nFOR ULTIMATE HELP, SEE THE EXAMPLE FILES FOUND IN /Designs/\n\n------------------------------------------------------------------------------\n\n\nThats it...\n\n\nCopyright 19(c)95 Ecstatica BBS\n@node INSTALL "Installation Info for Ecsta-Stat v2.00 by Instant"\n                     How do you install this utility?\n                     ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  Just Move the BBSCMD/S.info and SYSCMD/S.info to your BBS:commands dir!\n              Then Move the ecsta-tools/ directory to DOORS:\n\n                         The Files You''ll get are\n\n			bbscmd/s.info	- File to start Ecsta-Stat v2.0\n\n        		syscmd/s.info	- Runs Ecsta-Statin, info at login\n\nEcsta-tools/ecsta-stat/ecsta-log.gui	- GUI File for Ecsta-Login\nEcsta-tools/ecsta-stat/ecsta-log.rexx	- Ecsta-Login, status at logon!\nEcsta-tools/ecsta-stat/cookie		- Cookie file\nEcsta-tools/ecsta-stat/random		- Randomizer Programme\necsta-tools/ecsta-stat/ecsta-stat.guide - This File!\necsta-tools/ecsta-stat/ecsta-stat.rexx  - Main Executable\necsta-tools/ecsta-stat/ecsta-stat.cfg	- Configuration File\nEcsta-Tools/Ecsta-Stat/Ecsta-stat.pic	- Welcome Picture :)\nEcsta-Tools/Ecsta-Stat/AXXLEVELS.CFG	- Config File For Axx Levels, CHECK INSTALL FOR MORE INFO\nEcsta-Tools/Ecsta-Stat/BUGGS.TXT	- TExt about (if any) Buggs in current version\n\necsta-tools/ecsta-stat/designs/example.s        - Example Design file for Ecsta-Stat!\necsta-tools/ecsta-stat/designs/example.gui      - Example Design GUI for Ecsta-Stat!\necsta-tools/ecsta-stat/designs/mini.s           - Example Design File for Ecsta-stat\necsta-tools/ecsta-stat/designs/mini.gui         - Example Design GUI for Ecsta-stat\necsta-tools/ecsta-stat/designs/skan-4-stats.s   - Example Design File for Ecsta-stat\necsta-tools/ecsta-stat/designs/skan-4-stats.gui - Example Design GUI for Ecsta-Stat!\necsta-tools/ecsta-stat/designs/designs.txt	- Text file describing the Designs\n\necsta-tools/ecsta-stat/previews/example.iff	- Preview Picture of EXAMPLE Design\necsta-tools/ecsta-stat/previews/skan-4-stats.iff- Preview Picture of SKAN-4-STATS design\necsta-tools/ecsta-stat/previews/mini.iff	- Preview Picture of MINI Design!\n\nIf you''we used version 1.0 of ecsta-stat, you can delete the ecsta-stat.gui\nfile, because it is not needed anymore!\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node HISTORY "In 1963 JKF Was Shot, in 1988 The Berlin Wall Crumbled, in 1991 Saddam Got his Ass Kicked!, In 1995 Instant Released Ecsta Stat"\nLATEST VERSION IS ALWAYS THE ONE ON THE END OF THE LIST...\n\nHISTORY\n-------\nVersion 0.99 - Added Everything (NEVER RELEASED)\nVersion 1.00 - Added Ansi BackGround (UNRELEASED)\nVersion 1.01 - Added Cookie File (UNRELEASED)\nVersion 1.02 - Added Guide File (UNRELEASED)\nVersion 1.03 - Made Installation Script (UNRELEASED)\nVersion 1.04 - LHAed The Whole Thing and Sent it away for a beta release (Release #0.99)\nVersion 1.04m- Added ANSI and ASCII logo,Made Cookie Work (Release #1)\nversion 1.04z- Removed a screen-clear bug in the .gui file! (Release #1.01)\nVersion 1.5  - Added Design Files\nversion 1.6  - Changed Design Files Format because it became to much PES to make :)\nVersion 2.0  - Now Fully USER CONFIGURABLE!!!\nVersion 2.01 - Fixed some buggs, removed small design because of buggs, added new design commands\nVersion 2.10 - Added Access''o''meter command, added 2 new cookie commands\nVersion 2.11 - Fixed some more stuff, added Raytraced logo :)\n\n@Endnode\n@node CONTACT "First you turn left at 1st, then proceed allong west avenue for 30 blocks, when you come to a roadsight turn left and then right"\nCONTACT\n-------\nTo Contact The Author For Registration, Flames,  or Fan-Mail :)\ndo any of the following\n---\n\nVia Internet\n	Email : [email removed]\n        WWW   : http://powertech.no/~terjeba/ - Leave a Message in the GUestbook\n	IRC   : #amiga, #amiga!, #warez, #compuwar\n\nVia Modem\n  	      Ecstatica: +47-66900578  - The Home of Ecsta-Tools\n	Bumble Bee Land: +47-66xxxxxx  - Name: Instant (NUP,SYSPW)\n	 Basic Instinct: +47-xxxxxxxx  - Name: Instant\n	        OutPost: +46-xxxxxxxxx - Name: Instant\n	        Premium: +46-xxxxxxxxx - Name: Instant\n\nVia snailMail\n		Terje Alexander Barth\n		Fredtunveien 18\n		1370 Asker\n		Norway\n\n- Please send $5 if you REALLY Like this programme and want me to further develop it :)\nand for a registered version.\n\n- Please send $5 or more if you would like the Game ''UN - Conflict Jugoslavia''\n  to be furhter developed! and for a registered version when it''s finished!\n\nPlease state WHAT you are sending the money for.... i will also accept\nmore/less money, but for less you will only be mentioned in the programme docs\nif you want to..\n\n\n@ENDNODE\n@node OTHER\n\n       Other Usefull utilities to be released/or released by me are\n       ------------------------------------------------------------\n\nEcsta-Req    	- Requester for ASCII, AREXX and "STUFF"\nEcsta-Chat	- Chat Door\nEcsta-DS	- Local/Sysop Download Door\nEcsta-Who	- Who Door\nEcsta-Front	- FrontDoor\nEcsta-Desert	- Strategy Game for /X\nEcsta-Log	- Login Status door, Included with Ecsta-Stat v2.11\nEcsta-NewUser	- Newuser Script with LOTS of option (thnx to Dixy for giving me tips)\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',94102,2,0,NULL,NULL,'xta_st21','scan',1780048843);
INSERT INTO door_catalog VALUES('xta_st25','XTA-ST25.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XTA-ST25.LHA','Random','XIM','Random','2.5','Instant,','XTA','The Biggest /X Release Since Ecsta-Stat v2.1 Now With Even More Designs, 1 new cOOOL cmND and a hELP FILE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!',replace('         ÷-÷ Ecsta-Stat v2.5 ÷-÷\nThe Biggest /X Release Since Ecsta-Stat v2.1\nNow With Even More Designs, 1 new cOOOL cmND\nand a hELP FILE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\nProgramed By Instant, Release date: 7.Aug.95\n÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-÷-\n','\n',char(10)),'Ecsta-Stat.GuiDe',replace('@database Ecsta-Stat.GuiDe\n@$VER: Ecsta-Stat v2.50 By Instant/Independant - Guide File\n@node MAIN "Ecsta-Stat v2.50 (c) 08/95 Instant/Independant"\n\n\n\n\n\n\n                             Ecsta-Stat v2.50a\n                             Ecsta-Statin v1.0\n                               aXX&sOME v1.0a\n\n                                    By\n                            Instant/Independant\n\n\n    DISCLAIMER: The Author Takes no responsibility for any damage this\n      may cause you, your family, your pets, your friends, your house\n    your neighbourhood, your machine, any inventory in your house, your\n          country, your state or anything else you may think of.\n\ntO EnCourage further development and registration of any ECSTA-TOOLS programme\n      Please send me some cash  see CONTACTS for further information\n\n\n@endnode\n@node CONTENTS "Ecsta-Stat v2.50 (c) 08/95 Instant/Independant"\n\n                        Welcome to Ecsta-Stat v2.50\n                       The NEW Status Command for /X\n\n   Anyway: Press any of THEESE buttons to go to the corresponding page!\n\n                          @{" Installation " link "Install"}\n                          @{" Configure" link "config"}\n                          @{" Design" link "DESIGN"}\n                          @{" Contact " link "Contact"}\n                          @{" History " link "history"}\n                          @{" Other " link "OTHER"}\n\n\n\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node configure "How To Configure Ecsta-Stat"\n--------------------------\nCONFIGURING ECSTa-STAT.CFG\n--------------------------\nEdit the File Ecsta-Stat.cfg, here is a description of what\nthe different lines do.\n\nLine 1: example	- The Name of the Design File, found in Designs/\nLine 2: ESC[44;37m - Ansi Colour Coding on how the OUTPUT should look like\nLine 3: 1 or 2    - 1= ONE LINE COOKIE, 2= TWO LINED COOKIE (32Chars each)\n\nLine 4: THIS IS THE BACKGROUND;FOREGROUND COLOURS USED FOR AXXESS O METER WHEN CORRECT AXX\nLine 5: THIS IS THE BACKGROUND;FOREGROUND COLOURS USED FOR AXXESS O METER WITH ALL OTHER AXXS\n\n\nExample for line 2:   [44;37m Instant  [0m<- Username with blue backgrund and\n                      ^^^^^^^^                 white foreground\n                         What You Need to Write, and how it will look\n\nNo Need to Change LINE 4 or 5!!!\n\n\n-------------------------\nCONFIGURING AXXLEVELS.CFG\n-------------------------\nEdit the file AXXLEVELS.CFG after the following guidelines\n\n   line 1: NUMBER OF AXX LEVELS AVAILABLE (MAX 6 IN THIS VERSION )\nline 2-x : "AXXLEVEL NAME (MAX 8 LETTERS)" "AXX LEVEL IN NUMBERS"\n\nExample: Line 2: SYSOP 255\n                 ^^^^  ^^^\n                 |      `-= Axx Level #\n                 `-----= Axx Level Name\n\n\n------------------------\nCONFIGURING aXX&sOME.mSG\n------------------------\nEdit the file aXX&sOME.mSG after the following guidelines\n\nNO MORE THAN 6 LINES ALLOWED\nNO MORE THAN 55 CHARACTERS PER LINE\n\nThis Message will be shown when the user type ''s a''\n+ some more stuff\n\n\n@endnode\n@node design "How to Design your own Ecsta-Stat!"\n\n                       How to Design your OWN GUI!!!\n                       -----------------------------\n\nThis must be the FIRST status door with a 100% User Configurable Layout!\n\nYou can design your own layout with almost any editor, but i would personally\nreccomend a ANSI editor.\n\n------\nYOU NEED 2 FILES:\n\nDesign/designname.gui\ndesign/designname.s\n\nThe GUI file is just what it says, GUI\nThe S file is the DESIGN FILE!\n\nSEE THE EXAMPLE FOR MORE INFORMATION ON HOW TO MAKE IT!\n\n          -------------------------------------------------------\n          -------------------------------------------------------\n          -------------------------------------------------------\n\n\n                            FORMAT OF KEYWORDS:\n\n**********\nFOR USE IN designs/designname.s files!!!\n**********\n\n------------------------------------------------\n<keyword><lines from top>;<characters from left>\n------------------------------------------------\n\n-----------------------------------------------------------------------------\nKeyWord - What it IS\n-----------------------------------------------------------------------------\n  U#1;3	- UseRNumber\n  UN1;1	- UseRname\n  ND1;1	- Node User is Connected to!\n  UP1;2	- User Location/Group\n  UT1;1	- User Phone Number\n  UA1;2	- User Axx Level\n  MW1;1	- Messages Written\n  UF1;1	- Uploaded Files\n  DF1;1	- Downloaded files\n  UB1;1	- Uploaded Bytes\n  DB1;1	- Downloaded Bytes\n  UC1;1	- User Calls\n  LC1;1	- Last Call in SECONDS or Sumthing, from Beginning of year :) USE LL instead for date\n  TU1;1	- TIme Used today (minuttes)\n  TM1;1 - Current Time\n  TL1;1	- Time left today..\n  TA1;1	- Time Available/limit\n  DT1;1	- Downloaded Bytes today\n  SL1;1 - Special Login Date, REMOVES YEAR... But Otherwise Identical to LL\n  DL1;1	- Download Limit per day\n  LI1;1	- Lines Per Page User Has\n  AA1;1	- Area Axx Level (Take The length of Name from access/xxxx.info)\n  RF1;1 - File Ratio\n  RB1;1 - Byte Ratio\n  RT1:1 - Ratio (1:6 for Example)\n  RS1;1 - Special Ratio Format (Example: <BYTE ONLY> / <FILE ONLY> / <BYTE AND FILE>)\n  ND1;1 - Node Nr User connected to\n  CN1;1 - Conference Name\n  UX1;1 - User Expert Mode\n  LL1;1 - Date of Last Login\n  BN1;1	- Board Name\n  BS1;1	- Board Sysop\n  BC1;1	- Calls to bbs\n  BN1;1	- Number of Nodes\n  CF1;1	- Chat Flag\n  VR1;1	- Amix Version\n  CK1;1	- Cookie !!!!!! MUST BE 70!!!!!!!!! (EDIT ECSTA-STAT.CFG line:3 = 1)\n  C11;1 - Line 1 of SHORT Cookie! (32 Characters per line) (EDIT ECSTA-STAT.CFG line:3 = 2)\n  C21;1 - Line 2 of Short Cookie! (32 Characters per line) (EDIT ECSTA-STAT.CFG line:3 = 2)\n  BO1;1 - Baud rate User Connected at\n  AN1;1 - Active Nodes (xx - 2 nodes, xxx- 3 nodes, xxxx-4 nodes, and soo on)\n  AM1;1 - Access''o''Meter (NEED LOTS OF SPACE :) Check Example:MINI)\n\n-----------------------------------------------------------------------------\n\nFOR ULTIMATE HELP, SEE THE EXAMPLE FILES FOUND IN /Designs/\n\n------------------------------------------------------------------------------\n\n\nThats it...\n\n\nCopyright 19(c)95 Ecstatica BBS\n@node INSTALL "Installation Info for Ecsta-Stat v2.50 by Instant"\n\n                     How do you install this utility?\n                     ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  Just Move the BBSCMD/S.info and SYSCMD/S.info to your BBS:commands dir!\n              Then Move the ecsta-tools/ directory to DOORS:\n\n                         The Files You''ll get are\n\n			bbscmd/s.info	- File to start Ecsta-Stat v2.50\n        		syscmd/s.info	- Runs Ecsta-Statin, info at login\n\n\nEcsta-tools/ecsta-stat/ecsta-log.gui		- GUI File for Ecsta-Login\nEcsta-tools/ecsta-stat/ecsta-log.rexx		- Ecsta-Login, status at logon!\nEcsta-tools/ecsta-stat/cookie			- Cookie file\nEcsta-tools/ecsta-stat/random			- Randomizer Programme\nEcsta-tools/ecsta-stat/ecsta-stat.rexx		- Main Executable\nEcsta-Tools/Ecsta-Stat/Ecsta-stat.pic		- Welcome Picture :)\nEcsta-tools/Ecsta-stat/Ecsta-stat.hlp		- Ecsta-Stat Help Page!\nEcsta-tools/ecsta-stat/aXX&sOME.mSG		- AXX & SOme Message File, se ->Config<-\nEcsta-tools/Ecsta-stat/aXX&sOME.gUI		- AXX & some GUI file\n\nEcsta-tools/ecsta-stat/configs/ecsta-stat.cfg	- Configuration File\nEcsta-Tools/Ecsta-Stat/configs/AXXLEVELS.CFG	- Config File For Axx Levels, CHECK INSTALL FOR MORE INFO\n\nEcsta-Tools/Ecsta-Stat/docs/BUGGS.TXT	     	- TExt about (if any) Buggs in current version\nEcsta-tools/ecsta-stat/docs/ecsta-stat.guide 	- This Guide File\n\nEcsta-tools/ecsta-stat/designs/example.s        - Example Design file for Ecsta-Stat!\nEcsta-tools/ecsta-stat/designs/example.gui      - Example Design GUI for Ecsta-Stat!\nEcsta-tools/ecsta-stat/designs/mini.s           - Example Design File for Ecsta-stat\nEcsta-tools/ecsta-stat/designs/mini.gui         - Example Design GUI for Ecsta-stat\nEcsta-tools/ecsta-stat/designs/skan-4-stats.s   - Example Design File for Ecsta-stat\nEcsta-tools/ecsta-stat/designs/skan-4-stats.gui - Example Design GUI for Ecsta-Stat!\nEcsta-tools/ecsta-stat/designs/taco.gui		- Very Nice Design GUI\nEcsta-tools/ecsta-stat/designs/taco.s		- Very Nice Design file\nEcsta-tools/ecsta-stat/designs/designs.txt	- Text file describing the Designs\n\nEcsta-tools/ecsta-stat/previews/example.iff	- Preview Picture of EXAMPLE Design\nEcsta-tools/ecsta-stat/previews/skan-4-stats.iff- Preview Picture of SKAN-4-STATS design\nEcsta-tools/ecsta-stat/previews/mini.iff	- Preview Picture of MINI Design!\nEcsta-tools/ecsta-stat/previews/taco.iff	- Preview Picture of TACO design!\nEcsta-tools/ecsta-stat/previews/axx&some.iff	- Preview Picture of axx&sOME programme\nEcsta-tools/ecsta-stat/previews/previews.txt	- Short Info File\n\n\n\nIf you''we used version 1.0 of ecsta-stat, you can delete the ecsta-stat.gui\nfile, because it is not needed anymore!\n\n\nCopyright 19(c)95 Ecstatica BBS\n@endnode\n@node HISTORY "In 1963 JKF Was Shot, in 1988 The Berlin Wall Crumbled, in 1991 Saddam Got his Ass Kicked!, In 1995 Instant Released Ecsta Stat"\nLATEST VERSION IS ALWAYS THE ONE ON THE END OF THE LIST...\n\nHISTORY\n-------\nVersion 0.99 - Added Everything (NEVER RELEASED)\nVersion 1.00 - Added Ansi BackGround (UNRELEASED)\nVersion 1.01 - Added Cookie File (UNRELEASED)\nVersion 1.02 - Added Guide File (UNRELEASED)\nVersion 1.03 - Made Installation Script (UNRELEASED)\nVersion 1.04 - LHAed The Whole Thing and Sent it away for a beta release (Release #0.99)\nVersion 1.04m- Added ANSI and ASCII logo,Made Cookie Work (Release #1)\nversion 1.04z- Removed a screen-clear bug in the .gui file! (Release #1.01)\nVersion 1.5  - Added Design Files\nversion 1.6  - Changed Design Files Format because it became to much PES to make :)\nVersion 2.0  - Now Fully USER CONFIGURABLE!!!\nVersion 2.01 - Fixed some buggs, removed small design because of buggs, added new design commands\nVersion 2.10 - Added Access''o''meter command, added 2 new cookie commands\nVersion 2.11 - Fixed some more stuff, added Raytraced logo :)\nversion 2.20 - Made a new design, added more commands\nVersion 2.50 - Added AXX&SOME Sub Programme ''s a''\n\n@Endnode\n@node CONTACT "First you turn left at 1st, then proceed allong west avenue for 30 blocks, when you come to a roadsight turn left and then right"\nCONTACT\n-------\nTo Contact The Author For Registration, Flames,  or Fan-Mail :)\ndo any of the following\n---\n\nVia Internet\n	Email : [email removed]\n\nVia Modem\n  	      Ecstatica: +47-66900578  - The Home of Ecsta-Tools\n	        Premium: +46-xxxxxxxxx - Name: Instant\n\nVia snailMail\n		Terje Alexander Barth\n		Fredtunveien 18\n		1370 Asker\n		Norway\n\n- Please send $5 if you REALLY Like this programme and want me to further develop it :)\n  and for a registered version.\n\n@ENDNODE\n@node OTHER\n\n       Other Usefull utilities to be released/or released by me are\n       ------------------------------------------------------------\n\nEcsta-Req    	- Requester for ASCII, AREXX and "STUFF"\nEcsta-Chat	- Chat Door\nEcsta-DS	- Local/Sysop Download Door\nEcsta-Who	- Who Door\nEcsta-Front	- FrontDoor\nEcsta-Desert	- Strategy Game for /X\nEcsta-Log	- Login Status door, Included with Ecsta-Stat v2.11,v2.50\nEcsta-NewUser	- Newuser Script with LOTS of option (thnx to Dixy for giving me tips)\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',105194,5,0,NULL,NULL,'xta_st25','scan',1780048843);
