INSERT INTO door_catalog VALUES('ydl_ww04','YDL-WW04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/YDL-WW04.LHA','wwall','XIM','wwall',NULL,NULL,'YDL',':  \_   /_________________________\\_ ¬\ : .-''  /   / ¬\_  _  ¬\____  ¬\_ ___ ¬\/   / ¦ `-. /   /  _/   /  _/   /  _/  \____/   /.-''',replace('     ______                     _ __ ____   \n  :  \_   /_________________________\\_ ¬\ :\n.-''  /   / ¬\_  _  ¬\____  ¬\_ ___ ¬\/   / ¦\n`-. /   /  _/   /  _/   /  _/  \____/   /.-''\n.-''_\___   \_______\_______\_______\___/ `-.\n`--\______/--------------------------------''\n+------------------------------------------+\n| PReZeNTZ FRoM Da FaMouS WiLDTooLZ SeRieS |\n:        aN /X 3.x & 4.x XIM DooR          :\n        WiLD THiNG''s Spar Wall v0.4\nFast & eazy to use wall with color selection\n','\n',char(10)),'Wildwall.doc',replace('                                 Y O D E L\n                    p r e s e n t s   f r o m   t h e  \n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n                                S E R I E S\n\n                            an /X v3.x XIM door\n                        WiLD THiNG''s SPAR WALL v0.4\n\nThis  is  a  simple  to use wall door.  There surely are a lot of different\nwalls,  but either they do not work properly or they are to complicated and\nto  slow, so for me this is the optimal combination of speed and functions.\nBut judge yourself. \n\nInstallation:   Make  a dir called ''DOORS:WILDTOOLS/WILDWALL'', put there an\nempty file named WWALL.DAT (will be fixed with the next version), make copy\nthe  wall.info  icon  to  bbs:commands/bbscmd/  and do with it whatever You\nlike, or put it in Your bull.txt (~CC_WALL)\n\n\nCall  these  WiLDToolz Beta-Test and Release Sites for the newest WiLDToolz\nand to drop some suggestions or bug reports:\n\n- Country -------- Board Name ------ Board Numba ----- Write to -----------\n\n  Sweden           Edge Of Sanity    +46-346-81852     WiLD THiNG\n> Poland           Dixie             +48-71-575825     WiLD THiNG <\n  Poland           Opus              +48-22-188465     WiLD THiNG\n  Australia        Nirvana           +61-654-11672     Halloween \n\n---------------------------------------------------------------------------\n\n    > For the quickest answers call Dixie BBS, The Home Of WiLDToolz <\n\nReViSioN HiSToR¥:\n\nv0.1            first running version\nv0.2            added colorz\nv0.3            changed the prompt\nv0.4 09/09/94   adds username to line (suggestion made by Vinzi/Yodel)\n     27-09-94   PUBLIC RELEASE\n\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,  Crazy  Squaw, Calypso/GOD, KC, C/\Te¥e/Insane, Skrubier all\nmy Beta-Testers, and all others I forgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\n                     aND  LaZT  BuT  OF CoZ N°T LeaST\n              a BiG, FaT & HaiR¥ GReeT¥ T° a££ M¥ HoRNeD BRoS\n\nFranklin/Termos : YO, (I hate this RAP & similar shit), keep smilin'' & thx\n                  for da fonts\nuFoK/MySTiC     : thx FøR äLL THøZë µPPZ\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  \n  /        \  Vinzi/Yodel     : thx for da suggestions\n /___ () ___\ SiNTAX/WøT      : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\nRage against ZK : Go on like this\nLogic           : hey yer checkers  are da best \nMystic PL       : Czesc maluchy\nYodel           : hello bros... nice to be in YoDeL now\n\n','\n',char(10)),NULL,'auto-added',9115,2,0,NULL,NULL,'ydl_ww04','scan',1780048843);
INSERT INTO door_catalog VALUES('ydl_ww06','YDL-WW06.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/YDL-WW06.LHA','wwall','XIM','wwall','0.6','WiLD','YDL','|    ______   /X >3.x XiM       _ __ ____  | ¦    \_   /_________________________\\_ ¬\ : :    /   / ¬\_  _  ¬\____  ¬\_ ___ ¬\/   / ¦',replace('+--[ Spar Wall v0.6 by WiLD THiNG/YoDeL ]--+\n|    ______   /X >3.x XiM       _ __ ____  |\n¦    \_   /_________________________\\_ ¬\ :\n:    /   / ¬\_  _  ¬\____  ¬\_ ___ ¬\/   / ¦\n|   /   /  _/   /  _/   /  _/  \____/   /  |\n|  _\___   \_______\_______\_______\___/   |\n+--\______/--------------------------------+\n| PReZeNTZ FRoM Da FaMouS WiLDTooLZ SeRieS |\n:       WiLD THiNG''s Spar Wall v0.6        |\n|   Eazy 2 use wall with color selection   |\n|     BuGFiXeD & Rainbow CoLoRS added      |\n+------------------------------------------+\n','\n',char(10)),'Wildwall.doc',replace('                                 Y O D E L\n                    p r e s e n t s   f r o m   t h e  \n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n                                S E R I E S\n\n                            an /X v3.x XIM door\n                        WiLD THiNG''s SPAR WALL v0.6\n\nThis  is  a  simple  to use wall door.  There surely are a lot of different\nwalls,  but either they do not work properly or they are to complicated and\nto  slow, so for me this is the optimal combination of speed and functions.\nBut judge yourself. \n\nInstallation:   Make  a  dir  called  ''DOORS:WILDTOOLS/WILDWALL'',  copy the\nwall.info icon to bbs:commands/bbscmd/ and do with it whatever You like, or\nput it in Your bull.txt (~CC_WALL)\n\nEdit the tooltype ANONYMOUS=???  to your needs, it defines the level a user\nmust have to write anonymous messages.\n\n\nNOTE: THE RAINBOW OPTION MAKES THE BABY A BIT SLOWER ON OUTPUT WHEN IT HITS\n      A RAINBOWED LINE, THAT''S COZ /X CAN OUTPUT ONLY 200 CHARS AT ONCE AND\n      THERE ARE MORE THAN 400 IF A COMPLETE LINE IS RAINBOWED SO DONT SHOUT \n      AT ME...\n\nCall  these  WiLDToolz Beta-Test and Release Sites for the newest WiLDToolz\nand to drop some suggestions or bug reports:\n\n- Country -------- Board Name ------ Board Numba ----- Write to -----------\n\n  Sweden           Edge Of Sanity    +46-346-81852     WiLD THiNG\n> Poland           Dixie             +48-71-575825     WiLD THiNG <\n  Poland           Opus              +48-22-188465     WiLD THiNG\n  Australia        Nirvana           +61-654-11672     Halloween \n\n---------------------------------------------------------------------------\n\n    > For the quickest answers call Dixie BBS, The Home Of WiLDToolz <\n\nReViSioN HiSToR¥:\n\nv0.1            first running version\nv0.2            added colorz\nv0.3            changed the prompt\nv0.4 09/09/94   adds username to line (suggestion made by Vinzi/Yodel)\n     27-09-94   PUBLIC RELEASE\nv0.5 03-10-94   bugfix: creates wwall.dat when it''s not existing \n                        (it used to behave quite strange)\n                possibility of staying anonymous\nv0.6 05-10-94   made prompts CASE IN-SENSIBEL (rep. by Dansken)\n                added RAINBOW as color option\n\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,  Crazy  Squaw, Calypso/GOD, KC, C/\Te¥e/Insane, Skrubier all\nmy Beta-Testers, and all others I forgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\nA BIG BIG THANX TO THIS DUDES FOR GIVING ME SUGGESTIONS/BUG REPORTS TO MY\nDOORS:\n\n- Vinzi/YoDeL                   WiLDWall            \n- Bionic/YoDeL                  All of them :-)\n- Jarri/Union                   WiLDList & some others\n- Dansken/Hall Of Fame BBS      WiLDWall\n- DPJSoft/Opus BBS              WiLDBBS\n- BOGGAN                        WiLDWall\n\nuFoK/MySTiC     : thx FøR äLL THøZë µPPZ\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  GOT/Termos   : hehe my top uploader :-)\n  /        \  Yodel        : hello bros... nice to be in YoDeL now\n /___ () ___\ SiNTAX/WøT   : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\n\n','\n',char(10)),NULL,'auto-added',25804,14,0,NULL,NULL,'ydl_ww06','scan',1780048843);
INSERT INTO door_catalog VALUES('ydl_ww09','YDL-WW09.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/YDL-WW09.LHA','wwall','XIM','wwall','0.9',NULL,'YDL','¦_ _______               ___          _____¦ \\__   /______________|_  |________|   | /   /  \    _  \   __///______   /   |',replace('+---[  yODEl pREzENTz : SPAr WaLL v0.9 ]---+\n¦_ _______               ___          _____¦\n  \\__   /______________|_  |________|   |  \n    /   /  \    _  \   __///______   /   |  \n.--/   /|   \   \   \   \   |   /___/.   |-.\n| /______   |\______/\______|\____   |___| |\n|       |___|   yODEL pRESENTS   |___|     |\n| __/\__  aN /X 3.x & 4.x XIM dOOR cALLED: |\n| \ oO /  wILD tHING''S sPAR wALL v0.9      |\n`-/_\/_\-.     fAST & eAZY tO uSE     .----''\n    \/   `----------------------------'' >vNZ\n','\n',char(10)),'Wildwall.doc',replace('                                 Y O D E L\n                    p r e s e n t s   f r o m   t h e  \n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n                                S E R I E S\n\n                        an /X v3.x & v4.x XIM door\n                        WiLD THiNG''s SPAR WALL v0.9\n\nThis  is  a  simple  to use wall door.  There surely are a lot of different\nwalls,  but either they do not work properly or they are to complicated and\nto  slow, so for me this is the optimal combination of speed and functions.\nBut judge yourself. \n\nInstallation:   Make  a  dir  called  ''DOORS:WILDTOOLS/WILDWALL'',  copy the\nwall.info icon to bbs:commands/bbscmd/ and do with it whatever You like, or\nput it in Your bull.txt (~CC_WALL)\n\nEdit the tooltype ANONYMOUS=???  to your needs, it defines the level a user\nmust have to write anonymous messages.\n\nEdit  the LINES=??  tooltype, put in here the number of lines You''d like to\nhave  at  Your  wall  (default  is  20), just remember to either delete the\nwwall.data  or cut some lines so there aren''t more lines than You have set.\nNow  from  v0.8  You  can  safely set the number of lines to as much as You\nwish, no more will be shown than the user has set his linelength to.  ;)\n\nIf  You  want  sum  users  not  be  able to write on the wall create a file\ndoors:wildtools/wildwall/lamers.exclude  and  put  in their names, the wall\nwill be displayed to them, but they will not be able to write on it.\n\n\nNOTE: THE RAINBOW OPTION MAKES THE BABY A BIT SLOWER ON OUTPUT WHEN IT HITS\n      A RAINBOWED LINE, THAT''S COZ /X CAN OUTPUT ONLY 200 CHARS AT ONCE AND\n      THERE ARE MORE THAN 400 IF A COMPLETE LINE IS RAINBOWED SO DONT SHOUT \n      AT ME...\n\nCall  these  WiLDToolz Beta-Test and Release Sites for the newest WiLDToolz\nand to drop some suggestions or bug reports:\n\n- Country -------- Board Name ------ Board Numba ----- Write to -----------\n\n  Sweden           Edge Of Sanity    +46-346-81852     WiLD THiNG\n> Poland           Dixie             +48-71-575825     WiLD THiNG <\n  Poland           Opus              +48-22-188465     WiLD THiNG\n  Australia        Nirvana           +61-654-11672     Halloween \n\n---------------------------------------------------------------------------\n\n    > For the quickest answers call Dixie BBS, The Home Of WiLDToolz <\n\nReViSioN HiSToR¥:\n\nv0.1            first running version\nv0.2            added colorz\nv0.3            changed the prompt\nv0.4  09/09/94  adds username to line (suggestion made by Vinzi/Yodel)\n      27-09-94  PUBLIC RELEASE\nv0.5  03-10-94  bugfix: creates wwall.dat when it''s not existing \n                       (it used to behave quite strange)\n                possibility of staying anonymous\nv0.6  05-10-94  made prompts CASE IN-SENSIBEL (rep. by Dansken)\n                added RAINBOW as color option\nv0.7  07-11-94  added lamers.exlude           (sug. by Dansken)\n      10-11-94  minor bugfix (color choice is more secure now)\n                added LINES tooltype\n      14-11-94  fixed a little display bug (a CR was missing before\n                                           RAINBOW)\n                BETANOTE: uses now keyfile\nv0.7b 13-12-94  minor fix: changed prompts to HotKeys\nv0.7  ??-??-??  dunno anymore, some bugfixes\nv0.8  09-01-95  now handles numba of lines dynamically, no more than the\n                user has set are shown\nv0.9 19-02-95   minor bugfix\n     28-02-95   PUBLIC RELEASE\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,   Crazy   Squaw,   Calypso/GOD,   KC,SaL-One/TRSi/Boondocks,\nC/\Te¥e/Insane, Dalamar/LED, Skrubier all my Beta-Testers, and all others I\nforgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\nA BIG BIG THANX TO THIS DUDES FOR GIVING ME SUGGESTIONS/BUG REPORTS TO MY\nDOORS:\n\n- Vinzi/YoDeL                   WiLDWall            \n- Bionic/YoDeL                  All of them :-)\n- Jarri/Union                   WiLDList & some others\n- Dansken/Hall Of Fame BBS      WiLDWall\n- DPJSoft/Opus BBS              WiLDBBS\n- BOGGAN                        WiLDWall\n\n                           SPeCiaL THX & GReeTZ:\nAquarius/Outlaws: for helping me with that door coding stuff\nuFoK/MySTiC     : thx FøR äLL THøZë µPPZ\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  GOT/Termos   : hehe my top uploader :-)\n  /        \  Yodel        : hello bros... nice to be in YoDeL now\n /___ () ___\ SiNTAX/WøT   : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\n\n','\n',char(10)),NULL,'auto-added',41933,7,0,NULL,NULL,'ydl_ww09','scan',1780048843);
