INSERT INTO door_catalog VALUES('zil_s','ZIL-S.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ZIL-S.LHA',NULL,'XIM','__ ________ _______  _ _   _ _   ____',NULL,NULL,'ZIL','/ //  __  \_\     \_\/ \_\ / \_\ /  \ \ \_\\_/_/  / /_  __/_/  / //  / //    \ \ /  / / /  / //  / //  / //  /\  \_\',replace(' __ ________ _______  _ _   _ _   ____      \n/ //  __  \_\     \_\/ \_\ / \_\ /  \ \     \n\_\\_/_/  / /_  __/_/  / //  / //    \ \    \n      /  / / /  / //  / //  / //  /\  \_\   \n     / _/_/_/ _/_//  /_//_ /_//_ /_/  / /   \n    /      \_\  \_\     \_\   \_\__  / /    \n    \______/_/__/_/_____/_/___/_//__/_/     \n        no code - HACKERS - is safe         \nThe GODZILLA BBS - (804)437-8165 RINGDOWN   \nUSR 28.8 v.34/V.FC- ''030/25MHZ - 1.2 GIGS   \n                                            \nNice CLEAN ''S'' Replacement for SYSCMD/BBSCMD\n','\n',char(10)),NULL,NULL,NULL,NULL,2059,1,0,NULL,NULL,NULL,'scan',1780048844);
INSERT INTO door_catalog VALUES('zil_stng','ZIL-STNG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ZIL-STNG.LHA',NULL,'XIM','__ ________ _______  _ _   _ _   ____',NULL,NULL,'ZIL','/ //  __  \_\     \_\/ \_\ / \_\ /  \ \ \_\\_/_/  / /_  __/_/  / //  / //    \ \ /  / / /  / //  / //  / //  /\  \_\',replace(' __ ________ _______  _ _   _ _   ____      \n/ //  __  \_\     \_\/ \_\ / \_\ /  \ \     \n\_\\_/_/  / /_  __/_/  / //  / //    \ \    \n      /  / / /  / //  / //  / //  /\  \_\   \n     / _/_/_/ _/_//  /_//_ /_//_ /_/  / /   \n    /      \_\  \_\     \_\   \_\__  / /    \n    \______/_/__/_/_____/_/___/_//__/_/     \n        no code - HACKERS - is safe         \nThe GODZILLA BBS - (804)437-8165 RINGDOWN   \nUSR 28.8 v.34/V.FC- ''030/25MHZ - 1.2 GIGS   \n                                            \n     Star Trek TNG Trivia Game Door         \n','\n',char(10)),'STNG.Doc',replace('=============================================================================\n\n                  /X Clone by Shuyuki Tanaka/ZILLA Hackers\n              An /X Door Converted from C-Net By: LaserMannen\n                 Original C-Net Version By: Unknown Author\n\n=============================================================================\n\n			       WHAT IS STNG?:\n It is a kind of game like Trivial Pursuit. The game will ask you about 20\nquestions of 300 possible,that means that TRIVIA automaticly picks out 20\nquestions Randomly of 200. (Sorry for Bad Explanation. Im Tierd of this shit)\n\nINSTALLATION:\nThis is real Easy. Just place STNG in a directory called ''STNG'' in DOORS:.\nUnder /X v2.X, edit your BBS:COMMANDS/CUSTOMCOMMANDS file like this:\n\nTRIVIA        RM020DOORS:STNG/STNG.REXX\n\nor:\n\nWith /X v3.X or v3.X, just creat an ICON, and use an AIM tooltype.\n\nOk.. Since you UnLHAed your Archive, you should have at least the folowing\nfiles in :STNG/\n\n "STNG.Rexx" (The Rexx File) \n "STNG.Doc   (This Document)  \n "hiscores"    (high score data; will be created if not present)\n "STNGdat"     (file with 300 questions)\n\n-----------------------------------------------------------------------------\n\nSTNG File Format:\n\nquestion 1         =\nanswer 1           =  The correct answer must be preceded with an "!"\nanswer 2           =  Other answers must have a blank (or something except\nanswer 3           =  "!" and "-") before the answer.\nanswer 4           =  Omitted answers must consist only of a "-"\n  .                =\n  .                =  Here is an example of the questions/answers:\n  .                =\nWhat is two plus two?\n 22\n!4\n 6\n 8\nWho would you like to have SEX with?\n!Heather Locklear\n!Christy Thom\n Ralph Nader\n Ralph Crandon\n                   =\n                   =  NOTE: If there is more than one !, all ! marked\n                   =        answers will be counted correct.\n                   =        If there is no !, the user will always get it\n                   =        wrong.\n                   =\n                   =  You *MUST* have 4 answers per question, and a space\n                   =  or ''!'' between the first column and the answer.\n\n-------------------------------------------------------------------------\n\nThis AIM (AREXX) door is a clone of the ''TRIVIA'' arexx door.  MANY THANKS\nto LASERMANNEN!\n\n','\n',char(10)),NULL,NULL,7997,1,0,NULL,NULL,NULL,'scan',1780048844);
INSERT INTO door_catalog VALUES('ziplha','ZIPLHA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ZIPLHA.LHA',NULL,'XIM','Zipadder and LHA Adder 100% straight Arexx',NULL,NULL,NULL,'code.. not compressed, or anything... work great, very generic and simple.. just type: RX ZIPADDER FILES:2/ to add your',replace('Zipadder and LHA Adder 100% straight Arexx\ncode.. not compressed, or anything...\nwork great, very generic and simple.. just\ntype: RX ZIPADDER FILES:2/ to add your \nS:ZIPADDER.TXT to all those files.\nAnd the LHAADDER will just pull all the file\nfrom your BBSADS:ADDFILES.LHA/ path just lik\nskel''s util... so it kicks ass.. (like when\nya download a shitload of files from someone\nbbs, you can LHAADD em all... and not have\nto check them again on your BBS... )\n','\n',char(10)),'BLA1.TXT',replace('                 __________________________________________\n                |::::''       __                   ____    ø|\n                |::''        /_/\    ____________  \. /     | \n /\ \ ___  _____:''________/|\_\//\__\____      /_/\\//\____:________\n \/ //   /\   _/  _____/   |   /   __   /     /    \/    _/   _____/\n    /  _/  \_  \  __/___   |__/_   /___/    ./   __  __   \   __/________\n   /            \ /     \  l    \ /    "\  //     \  /     \  /      \  ø:\n  /_____ /\ ____/_______/_______/________\ / \_____\/______/_________/   |\n   LnG \/  \/   :     :        ____      \/    /_/\ .cOLa..:             |\n          :     |  - -o- -     \ ./            \_\/     .::|             |\n          |     |_____:_________\/____________________.::::|   oO..      |\n          |                                          ø:                  |\n  - -->   |                YOU DID JUST ENTER         |                  |\n          |                                           |                  |\n          |                 eMPIrE <> PaLACe          |           !      |\n          |                                           |                  |\n:         |                                           |      <-- -       |\n::.       |                                           |                  |\n:::: - --*-    RUNNING A2ooo / 4omHZ - 1.2GB SPACE -.3 nODES zYX -*-- -  |\n:::.      :______________________________________.::::|                  |\n::::.                              |       -                             |\n:::.         - --> YaR MasTeR iS  : Mr.SONy                              |\n:::.                               |                                     |\n:::::.             aND dA FirsT onE BehiND iS KaNE / DlT <-- -       /   |\n::::::.                            | - -->                          / /  |\n::::::::.                          |_____________________________________|\n::::::::::........    RePLaY foR da nuMbeRs AnD nEw nuPE   ....  .     ...\n:::::::::::::::::::::::::::: IsDN coMMinG SooN :::::::::::::::::::::::::::\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n','\n',char(10)),NULL,NULL,12836,11,0,NULL,NULL,NULL,'scan',1780048844);
INSERT INTO door_catalog VALUES('zk_ae230','ZK-AE230.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ZK-AE230.LHA','ACP','XIM','ACP',NULL,NULL,'ZK','GdH._______________/     \   · 2 o o 8 · _/___ _  ¬\     /    __/   fReiKOrPs!! /       ____\   __    ¬\G^S!',replace('             _ __________  ZoNDERKoMMANDo!  \nGdH._______________/     \   · 2 o o 8 ·    \n  _/___ _  ¬\     /    __/   fReiKOrPs!!    \n /       ____\   __    ¬\G^S!               \n/       /     \_  /      \_Ami Express v3.20\n\_____         /_/        /    1 0 0 %      \n      \_______/  \_______/                  \n  UT MED DET SVARTA PACKET..  VIT MAKT!!!!\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n             