INSERT INTO door_catalog VALUES('z_patz10','Z_PATZ10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/Z_PATZ10.LHA','PatchTZ','XIM','PatchTZ',NULL,NULL,NULL,'_!__    /|  |  _____!_    /   _ \/   _____!_ : /   /_|  |  \_   :/   /_:     \   \_   :/ /   /  |  |   /   /   /  |  T   \_  /   /',replace('_:_______:.:!_______:______T\___  ________:_\n_!__    /|  |  _____!_    /   _ \/   _____!_\n : /   /_|  |  \_   :/   /_:     \   \_   :/\n  /   /  |  |   /   /   /  |  T   \_  /   / \n /_______| _!______/_______|  |____/_____/  \n=========!  :==CoRPoRaT|oN-! -+-====LTm=====\n[] PatchTZ V1.0 - Removes TZ in /X & Co ! []\n{---[ B·D - Where The Wares Come From! ]---}\n','\n',char(10)),'PatchTZ.Doc',replace('          ________  ____  _________\n         |        \/    \ \       /     [rAt!]\n       __|___     /     \\/   ___/____\n      /     _____/\______/    \__     |   ________  _______  _________\n     /             \     |      |     |  |        \/       \ \       /\n     \___________  /     |____________|__|___     /    _    \/   ___/____\n                 \/------''            /     _____/\    |     \   \__     |\n                                     /             \   _      \    |     |\n                                     \___________  /___|______/__________|\n                                                 \/\n                             -  corporation  -\n\n                                PatchTZ V1.0\n\n                           (C) 1994 by Lynxx/ZZC\n\n                          Short Docs by Joker/ZZC\n\n\n                              -  DISCLAIMER  -\n\n Whatever  you do with this program - it''s YOUR thing. You may not use this\n programs for profit, professional use, any military misuse or that belongs\n to test with animals. We are not responsible for any damage that may occur\n with this program nor we can pay for any damage. This program is so called\n GIFTWARE,  if you like it send us anything. It is not PUBLIC DOMAIN in any\n way.  It is allowed to spread it via electronic nets but NOT to include it\n on  any  collection  disks  except Fred Fishs Amiga Libdisks. Bugreports &\n suggestions are RECOMMENDED !\n\n\n                               -  OVERVIEW  -\n\n Did  you ever start Snoopdos or similar programs together with Ami Express\n and looked at the output? You will see tons of calls that look like this:\n \n  Snoopdos Output:\n  Express     OPEN    Ram:ENV/TZ           fail\n\n This  routine  gets  called  4 times (!) everytime a key is pressed in /X,\n thus  slowing  the  whole thing down and causing some strange sideeffects,\n like extremely slow description-snapping into /X, weird delays while doing\n something in /X and similar nice effects.\n I especially loved the one, where you CAN´T login local via F2 into /X on\n some configurations, because at the password prompt it always did a return\n after entering a char.\n \n           ALL THESE PROBLEMS ARE NOW FIXED BY THIS LITTLE PATCH!\n\n\n                                -  USAGE  -\n\n Simply run PatchTZ by typing the filename from shell or by double clicking\n on it´s icon from Workbench. You will get a litte graphical user interface\n where  you can select the source and destination path and filename of your\n Ami Express file to be patched.\n Simply select the file EXPRESS in your BBS: drawer and it will be patched\n and  saved  under a selectable filename and path (can be the same). All in\n all,  only  4  bytes  are  changed,  so  no  reason to suspect any kind of\n backdoor  behind  this  patch. All it does is removing the annoying ENV:TZ\n shit  from  your  BBS-software.  Surprisingly (really ?) it works with all\n versions of AmiExpress AND clones of it. Don''t worry about the TZ variable\n because  you  can still use it. The only tool we know of that MIGHT use TZ\n is  Pretty  Good  Privacy  (PGP),  actually  it''s  only  to  keep  up some\n compatibility to UNIX & MS-DOS (do we need this ?).\n\n  History:\n  ---------\n  V 1.0 - First release and seems to work great !\n\n\n   Watch out for other high quality tools by Zig Zag Corporation soon.\n\n\n           Greetings must go to the following dudes and groups:\n\n  Freddy Krueger/GOD, Jaf/GOD, Re/Y\o/Mst, Byteandi/Mst, Whiz/EP, G.E.M.,\n    Noisy Belch, Sigma Seven, Calypso/Logic, Planetmaster/TSL?, Piranha,\n Bytemaster/LST, Buster & Fuzz, C.I.P., Jazzytech/TLS, Ernesto/RDC, Shadow,\n    Ronny & Error, Mr. Mistral, -[RAT]-,The Rat, Avenger, Mr. Hell, DOC,\n    Radar, Thomas!/SP, Wormeater, Picard/ATX, Lithium/ATX, SCSI, Delta,\n   Andy/SP, Crackdown/Mst, Sven the Creator/5D, Snow/LGC, Subhumanz/LSD,\n   Kitaro/FLT, Illuminator, Caos, Zaz/TRSI, Dr.Grell, Gigabyte, Axe/Mst,\n Spy/Mst, Marky&Power/BLH, Mincer/CLX, BBC/Motion, \X/arhawk/Logic, Jesus,\n     Fakebuster, Andy/Motion, the whole Phonedation Crew, BuB/ATX, MiKE\n    Hammer/FTH, DR.DRe!/TRSI, Gandalf/FTH, Scorpio/SR, Gazzer/DTL, Rave,\n   Sintax/WøT, Empire/MST, Wyld Tyme/CSL?, TEMPO/SA, Swerx/Føda, Autopsy,\n  Pencl/ARISE, Danzig/G^S, RedSkin/G^S, Dux, DevilStar, Master and all the\n                     others we´ve forgotten to greet.\n\n   A special for Midi Messiah: For GOD''S SAKE we hope that you are still\n                           alive down in Serbia !\n\n\n                Call our boards to get our next releases:\n \n         __________:  __|___________  __________T\___________________\n         \         |    |          /  \         |        |          /\n          \  ____  |    |  _____  /    \  ____  |   ___  |  _____  /\n          /\/ _____|    |  \    \/     /\/ _____|        |  \    \/\n         /         |    |        \    /         |    T   |        \\n        /__________|    |    _____\  /__________|    |___|    _____\\n                   !    :----''                  |    !   `----''\n                        - C o R P o R a T | o N -\n\n Foxx´s Den        - (ZZC-WHQ) - +49-275-3852   USR DUAL 16.8\n                                 +49-275-31372  ZyXEL 19.2\n\n Byteriders BBS    - (ZZC-GHQ) - +49-981-970900 Two Nodes Ringdown\n                                  (USR DUAL 16.8 and USR DUAL 14.4)\n\n','\n',char(10)),NULL,'auto-added',9190,7,0,NULL,NULL,'z_patz10','scan',1780048844);
