INSERT INTO door_catalog VALUES('z_w8va11','Z_W8VA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/Z_W8VA11.LHA','WaitValidate','XIM','WaitValidate',NULL,NULL,NULL,'____    / / /_________    /  \   /_______ /    / / / \__\_  /    / /  \_/ \__\_ /   _/_/ /    / / /   _/_/    /    / /',replace(' _________  / /_____________/\     _______  \n ____    / / /_________    /  \   /_______  \n   /    / / / \__\_  /    / /  \_/ \__\_    \n  /   _/_/ /    / / /   _/_/    /    / /    \n /______/ /______/ /______/____/______/     \nC=o=R=P/o/R=aT=|=o=n   / /          [-LTm-] \n[] WaitValidate V1.1 - sysops use this !! []\n{---[ B·D - Where The Wares Come From! ]---}\n','\n',char(10)),'WaitValidate.DOC',replace('          ________  ____  _________\n         |        \/    \ \       /     [rAt!]\n       __|___     /     \\/   ___/____\n      /     _____/\______/    \__     |   ________  _______  _________\n     /             \     |      |     |  |        \/       \ \       /\n     \___________  /     |____________|__|___     /    _    \/   ___/____\n                 \/------''            /     _____/\    |     \   \__     |\n                                     /             \   _      \    |     |\n                                     \___________  /___|______/__________|\n                                                 \/\n                             -  corporation  -\n\n                             WaitValidate V1.1\n\n                           (C) 1994 by Lynxx/ZZC\n\n                           Short Docs by Foxx/ZZC\n\n\n                              -  DISCLAIMER  -\n\n Whatever  you do with this program - it''s YOUR thing. You may not use this\n programs for profit, professional use, any military misuse or that belongs\n to test with animals. We are not responsible for any damage that may occur\n with this program nor we can pay for any damage. This program is so called\n GIFTWARE,  if you like it send us anything. It is not PUBLIC DOMAIN in any\n way.  It is allowed to spread it via electronic nets but NOT to include it\n on  any  collection  disks  except Fred Fishs Amiga Libdisks. Bugreports &\n suggestions are RECOMMENDED !\n\n\n                              -  OVERVIEW  -\n\n You are using a program that writes to a device very early but if it fails\n (esp.  when  the device is not validated) it might lock up the system ? WV\n waits until devices are validated.\n\n\n                               -  USAGE  - \n\n WV  aka  WaitValidate  is a sysops must ! It might happen that the machine\n crashes  when  it  is  writing  to  somewhere and so the drive will not be\n validated.  When  this  drive is used by the BBS to store data to and it''s\n loaded and a user logs in it will hang because it can''t write to the drive\n as  long as it is not validated. So you could wait everytime after a reset\n for  a  time  where all drives are 100% validated (or bad luck they have a\n r/w-error  -  yuk!)  or  you  use  this tool ! You just give the drives it\n should  wait  for and maybe a timeout when it should quit waiting (default\n is  15  minutes)  -  e.g. "WV DH0: DH1: 5" so it waits for DH0: & DH1: the\n maximum  of  5  minutes.  If  the timeout is reached WV will return a WARN\n (code 5). Check the included script !\n\n  History:\n  ---------\n  V 1.0 - First release - it WORKS !\n  V 1.1 - No special changes - some cosmetics anyway\n\n   Watch out for other high quality tools by Zig Zag Corporation soon.\n\n\n           Greetings must go to the following dudes and groups:\n\n  Freddy Krueger/GOD, Jaf/GOD, Re/Y\o/Mst, Byteandi/Mst, Whiz/EP, G.E.M.,\n    Noisy Belch, Sigma Seven, Calypso/Logic, Planetmaster/TSL?, Piranha,\n Bytemaster/LST, Buster & Fuzz, C.I.P., Jazzytech/TLS, Ernesto/RDC, Shadow,\n    Ronny & Error, Mr. Mistral, -[RAT]-,The Rat, Avenger, Mr. Hell, DOC,\n    Radar, Thomas!/SP, Wormeater, Picard/ATX, Lithium/ATX, SCSI, Delta,\n   Andy/SP, Crackdown/Mst, Sven the Creator/5D, Snow/LGC, Subhumanz/LSD,\n   Kitaro/FLT, Illuminator, Caos, Zaz/TRSI, Dr.Grell, Gigabyte, Axe/Mst,\n Spy/Mst, Marky&Power/BLH, Mincer/CLX, BBC/Motion, \X/arhawk/Logic, Jesus,\n     Fakebuster, Andy/Motion, the whole Phonedation Crew, BuB/ATX, MiKE\n    Hammer/FTH, DR.DRe!/TRSI, Gandalf/FTH, Scorpio/SR, Gazzer/DTL, Rave,\n   Sintax/WøT, Empire/MST, Wyld Tyme/CSL?, TEMPO/SA, Swerx/Føda, Autopsy,\n  Pencl/ARISE, Danzig/G^S, RedSkin/G^S, Dux, DevilStar, Master and all the\n                     others we´ve forgotten to greet.\n\n   A special for Midi Messiah: For GOD''S SAKE we hope that you are still\n                           alive down in Serbia !\n\n\n                Call our boards to get our next releases:\n \n         __________:  __|___________  __________T\___________________\n         \         |    |          /  \         |        |          /\n          \  ____  |    |  _____  /    \  ____  |   ___  |  _____  /\n          /\/ _____|    |  \    \/     /\/ _____|        |  \    \/\n         /         |    |        \    /         |    T   |        \\n        /__________|    |    _____\  /__________|    |___|    _____\\n                   !    :----''                  |    !   `----''\n                        - C o R P o R a T | o N -\n\n Foxx´s Den        - (ZZC-WHQ) - +49-275-3852   USR DUAL 16.8\n                                 +49-275-31372  ZyXEL 19.2\n\n Byteriders BBS    - (ZZC-GHQ) - +49-981-970900 Two Nodes Ringdown\n                                  (USR DUAL 16.8 and USR DUAL 14.4)\n\n','\n',char(10)),NULL,'auto-added',7810,7,0,NULL,NULL,'z_w8va11','scan',1780048844);
